/* 中英双语精编（自动合并生成，请勿手工编辑） */
(window.LINGUA_BOOK=window.LINGUA_BOOK||{}).condense=Object.assign(window.LINGUA_BOOK.condense||{},{"front-matter-001-accessibility-statement":{"title":{"en":"Accessibility Statement","zh":"无障碍声明"},"summary":{"en":"This statement explains how Essentials of Linguistics, 2nd edition meets eCampusOntario's Virtual Learning Strategy accessibility requirements, and how the authors aim to go beyond the minimum standards by developing conventions for linguistic diagrams, formalisms, and notation. It lists the measures already taken, the formats the ebook can be exported to, and the ways readers can send feedback.","zh":"本节说明《语言学基础》第二版如何满足 eCampusOntario“虚拟学习策略”的无障碍要求，并交代作者不满足于最低标准，还针对语言学图表、形式化表达和符号系统研究更专门的无障碍规范。文中列举了已经采取的各项措施、电子书可导出的格式，以及读者反馈的渠道。"},"points":[{"en":"The textbook conforms to eCampusOntario's Virtual Learning Strategy accessibility requirements for digital learning content.","zh":"教材符合 eCampusOntario“虚拟学习策略”对数字学习内容提出的无障碍要求。"},{"en":"Pages are navigable by screenreader, and every non-decorative image and diagram carries alt-text.","zh":"页面可用屏幕阅读器浏览，所有非装饰性的图片和图表都配有替代文本。"},{"en":"Syntax and morphology trees use bracketed alt-text while easier audio-friendly ways of conveying hierarchy are explored.","zh":"句法与形态树形图目前采用括号式替代文本，作者正探索更便于音频理解层级结构的表达方式。"},{"en":"Glossed examples sit in tab-navigable tables, are tagged as non-English, and high contrast colour is used throughout.","zh":"带注释的例子放在可用 Tab 键浏览的表格中，并在适用时标记为非英语，全书采用高对比度配色。"},{"en":"The ebook exports to PDF or EPUB, and Pressbooks supports zooming the font size by 200% on all platforms.","zh":"电子书可导出为 PDF 或 EPUB，Pressbooks 在所有平台均支持把字号放大约 200%。"},{"en":"As of the February 28th, 2022 soft launch some features were still pending, and feedback by email is welcome.","zh":"截至 2022 年 2 月 28 日软启动时，部分功能尚未实现，作者欢迎读者通过邮件反馈。"}],"terms":[{"en":"accessibility","zh":"无障碍（可及性）","defEn":"The degree to which content can be used by people with disabilities and other diverse users.","defZh":"指内容能被残障人士及其他各类用户顺利获取和使用的程度。"},{"en":"screenreader","zh":"屏幕阅读器","defEn":"Software that reads on-screen text aloud for users who cannot read it visually.","defZh":"一种把屏幕上的文字朗读出来的辅助软件，供无法用视觉阅读屏幕的用户使用。"},{"en":"alt-text","zh":"替代文本","defEn":"A short written description attached to a non-decorative image or diagram.","defZh":"附加在非装饰性图片或图表上的简短文字说明，供屏幕阅读器朗读。"},{"en":"International Phonetic Alphabet (IPA)","zh":"国际音标","defEn":"A standard set of symbols for representing the sounds of spoken language.","defZh":"一套用统一符号记录人类语言语音的国际通用标音系统，即通常所说的音标。"}],"examples":[{"text":"Pages are navigable by screenreader. (Note: Firefox does not seem to work well.)","noteEn":"One listed measure, with a caveat about browser support for screenreader navigation.","noteZh":"所列措施之一，并附带说明某个浏览器在屏幕阅读器导航方面表现不佳。"},{"text":"For syntax and morphology trees, the alt-text is currently formatted as a bracketed diagram","noteEn":"Shows how tree diagrams are described textually for now, pending a better audio format.","noteZh":"说明树形图目前以何种文字方式描述，更好的音频呈现方式仍在探索中。"},{"text":"Pressbooks supports zooming the font size by 200% across all of its platforms.","noteEn":"A platform-level feature that makes the text easier to enlarge for low-vision readers.","noteZh":"平台层面的功能，便于低视力读者把正文字号放大到两倍。"}],"body":[{"en":"This textbook meets the accessibility requirements of eCampusOntario's Virtual Learning Strategy. The authors also say that they want to go beyond the minimum standards: they are researching and developing accessibility conventions specific to linguistic diagrams, formalisms, and notation, and they list several measures taken so far to improve access.","zh":"本教材符合 eCampusOntario“虚拟学习策略”的无障碍要求。作者同时表示，他们并不止步于最低标准，还要针对语言学图表、形式化表达和符号系统研究并制定专门的无障碍规范，并列举了为提升可及性已经采取的若干措施。"},{"en":"Pages can be navigated with a screenreader, and alt-text is provided for every non-decorative image and diagram. The alt-text for syntax and morphology trees currently takes the form of a bracketed diagram, though the authors are looking for ways to convey hierarchical structure that are easier to follow in audio. A definition file covering special characters of the International Phonetic Alphabet is planned for screenreaders. Graphs, charts, and maps are described in writing, glossed linguistic examples are placed in tables that can be reached by tabbing, high contrast colour is used, and many passages also appear in parallel video format, where the text serves as a transcript.","zh":"页面可以用屏幕阅读器浏览，所有非装饰性的图片和图表都提供替代文本。句法和形态树形图的替代文本目前采用括号式图表达，作者正探索更便于音频理解层级结构的方式。国际音标特殊字符的屏幕阅读器定义文件即将推出。图形、图表和地图在正文中用文字加以描述；带注释的语言学例子以可用 Tab 键浏览的表格呈现，并在适用时标记为非英语；全书使用高对比度配色；许多内容还配有并行视频，文字即视频的文字稿。"},{"en":"The ebook can be exported as PDF or EPUB, PDF versions can be printed, and all interactive content is available in the backmatter of exported copies. Pressbooks supports zooming the font size by 200% on every platform. Feedback is welcome, both about what is working well and about issues that were overlooked or could be improved, by email at teaching.in.linguistics@gmail.com. As of the soft launch on February 28th, 2022, not all of these accessibility features had been implemented, but the authors plan to keep working on them through the rest of 2022.","zh":"电子书可导出为 PDF 或 EPUB，PDF 版本可以打印，导出副本中的所有交互内容都放在书末附录中。Pressbooks 在所有平台上都支持把字号放大约 200%。作者欢迎读者通过 teaching.in.linguistics@gmail.com 反馈意见，无论是做得好的地方，还是被忽略或仍可改进的问题。截至 2022 年 2 月 28 日“软启动”时，这些无障碍功能尚未全部实现，但作者计划在 2022 年余下的时间里继续推进。"}]},"front-matter-002-about-the-authors":{"title":{"en":"About the Authors","zh":"作者简介"},"summary":{"en":"This section introduces the authors of the textbook. It describes the Teaching in Linguistics Community of Practice (TiLCoP), the Canadian instructors' group whose collaboration produced the book, and gives a short biography of each of the seven contributors, covering their positions, training, research interests, and the territories on which their institutions stand.","zh":"本节介绍本教材的作者群体。先说明语言学教学实践共同体（TiLCoP）这一加拿大语言学教师协作组织的由来，以及它如何促成本书和配套播客等成果；随后逐一简介七位作者，包括其任职院校、学术训练背景、主要研究兴趣，以及各人所在院校所处的原住民传统领地。"},"points":[{"en":"TiLCoP is a community of linguistics instructors at Canadian universities who meet to discuss teaching and pedagogical research.","zh":"TiLCoP 是加拿大各大学语言学教师组成的实践共同体，定期聚会讨论教学实践与教学法研究。"},{"en":"It formed in 2020, when instructors needed shared resources and support during a rapid shift in teaching modality.","zh":"该组织成立于 2020 年，当时教师因教学模式骤变而亟需共享资源与相互支持。"},{"en":"Its collaboration produced a companion podcast, a journal special issue, and this textbook.","zh":"其协作成果包括一档配套播客、一期期刊专刊，以及这本教材。"},{"en":"The seven contributors hold teaching-stream or research-stream positions at universities across Canada.","zh":"七位作者分别在加拿大各地大学担任教学型或研究型教职。"},{"en":"Their research covers phonetics, phonology, morphology, syntax, semantics, pragmatics, psycholinguistics, and sociolinguistics.","zh":"他们的研究涵盖语音学、音系学、形态学、句法学、语义学、语用学、心理语言学与社会语言学。"},{"en":"Several authors acknowledge the Indigenous territories on which their institutions are located.","zh":"多位作者说明了其所在院校所处的原住民传统领地。"}],"terms":[{"en":"Teaching in Linguistics Community of Practice (TiLCoP)","zh":"语言学教学实践共同体（TiLCoP）","defEn":"A Canadian community of linguistics instructors sharing teaching practice and pedagogical research.","defZh":"由加拿大语言学教师组成的共同体，共同分享教学实践与教学法研究成果。"},{"en":"psycholinguistics","zh":"心理语言学","defEn":"The study of the mental processes and representations involved in language comprehension and production.","defZh":"研究语言理解与产出所涉及的心理过程与心理表征的学科。"},{"en":"formal semantics","zh":"形式语义学","defEn":"The study of linguistic meaning using formal, logic-based systems of representation.","defZh":"运用形式化的逻辑表征系统研究语言意义的学科分支。"},{"en":"multiethnolect","zh":"多民族方言","defEn":"A contact variety that emerges among youth from diverse immigrant backgrounds in a city.","defZh":"在城市中由不同移民背景的青少年共同形成的一种接触变体。"},{"en":"clausal architecture","zh":"小句结构","defEn":"The internal structural organization of clauses and the positions of their elements.","defZh":"小句内部的结构组织方式以及各组成成分所处的位置。"}],"examples":[{"text":"Word to the Whys","noteEn":"A companion podcast produced for Introductory Linguistics courses by the TiLCoP collaboration.","noteZh":"TiLCoP 协作产出的一档播客，作为语言学导论课程的配套资源。"},{"text":"a special issue of the Canadian Journal of Linguistics","noteEn":"One of the collaborative projects that grew out of the group's regular meetings.","noteZh":"该组织定期聚会所催生的协作项目之一。"},{"text":"Dish With One Spoon wampum agreement between the Haudenosaunee and Anishinaabe Nations","noteEn":"The treaty territory where one of the authors lives and works.","noteZh":"其中一位作者生活与工作所在的条约领地。"},{"text":"directional particles in Niuean (Polynesian)","noteEn":"A current research topic of one contributor, alongside work on K'iche' (Mayan).","noteZh":"一位作者当前的研究课题，此外还从事 K'iche'（玛雅语族）的田野调查。"}],"body":[{"en":"The authors of this textbook belong to the Teaching in Linguistics Community of Practice (TiLCoP), a group of linguistics instructors at Canadian universities who meet regularly to discuss their teaching and pedagogical research. TiLCoP came together in 2020, when the pandemic forced a rapid shift in teaching modality and instructors needed shared resources and mutual support. Their collaboration has since produced several projects: Word to the Whys, a companion podcast for introductory linguistics courses; a special issue of the Canadian Journal of Linguistics; and this textbook.","zh":"本教材的作者均属于语言学教学实践共同体（TiLCoP）。这是加拿大各大学语言学教师组成的团体，成员定期聚会，讨论教学实践与教学法研究。该共同体成立于 2020 年，当时疫情迫使教学模式骤然改变，教师亟需共享资源与相互支持。此后，他们的协作催生了若干项目：语言学导论课程的配套播客 Word to the Whys、一期《加拿大语言学杂志》专刊，以及这本教材。"},{"en":"The seven contributors teach and research at institutions across Canada, among them McMaster University, Queen's University, the University of Toronto Mississauga, Simon Fraser University, the University of Toronto (St. George), the University of Guelph-Humber, the University of Victoria, and Seneca College. Several authors name the Indigenous peoples on whose traditional territories their campuses stand, referring to the Dish With One Spoon wampum agreement and the treaty lands of the Mississaugas of the Credit.","zh":"七位作者任教并从事研究于加拿大各地院校，包括麦克马斯特大学、女王大学、多伦多大学密西沙加校区、西蒙弗雷泽大学、多伦多大学圣乔治校区、圭尔夫—汉博大学、维多利亚大学与塞内卡学院。多位作者在文中列出了其校园所处的原住民传统领地，并提及豪德诺索尼与阿尼什纳比民族之间的「一勺之盘」贝壳带协议，以及密西沙加克雷迪特人的条约领地。"},{"en":"Their research interests are broad. They work on the phonetics and phonology of signed and spoken languages, historical phonology and sound change, morphology and syntax, formal semantics and pragmatics, psycholinguistics, and variationist and sociocultural approaches to language change. Specific topics include the interfaces between the formal modules of grammar, sentence comprehension, cross-linguistic variation in clausal architecture, and the emergence of a multiethnolect in Toronto. Their work has appeared in journals such as Language, Linguistic Inquiry, Natural Language and Linguistic Theory, and Glossa.","zh":"他们的研究兴趣广泛，涉及手语与口语的语音学和音系学、历史音系学与音变、形态学与句法学、形式语义学与语用学、心理语言学，以及从变异社会语言学和社会文化视角研究语言变化。具体课题包括语法各形式模块之间的接口、句子理解、小句结构的跨语言差异，以及多伦多地区多民族方言的兴起。其成果发表于 Language、Linguistic Inquiry、Natural Language and Linguistic Theory、Glossa 等期刊。"}]},"front-matter-003-acknowledgements":{"title":{"en":"Acknowledgements","zh":"致谢"},"summary":{"en":"Essentials of Linguistics, 2nd Edition was funded by the Government of Ontario through eCampusOntario's support of the Virtual Learning Strategy. The book is the work of a large team of authors and an even larger team of supporters, among them fellow TiLCoP members, language experts, reviewers, an artist, and an accessibility adviser. The authors thank their linguistics students, past and present, for inspiring them to strive for excellence and justice in teaching linguistics.","zh":"《语言学基础》第二版由安大略省政府出资，并通过 eCampusOntario 对虚拟学习战略的支持得以完成。全书由人数众多的作者团队撰写，更有规模更大的支持者群体参与，包括 TiLCoP 同仁、语言专家、审阅者、美术设计者与无障碍设计顾问。作者最后感谢历届语言学学生，是他们激励作者在语言学教学中追求卓越与公正。"},"points":[{"en":"Funding comes from the Government of Ontario through eCampusOntario's support of the Virtual Learning Strategy.","zh":"本项目由安大略省政府出资，并借助 eCampusOntario 对虚拟学习战略的支持得以完成。"},{"en":"Fellow TiLCoP members Daniel Currie Hall, Liisa Duncan, Martin Kohlberger, and Tim Mills offered pedagogical insight and wise counsel.","zh":"TiLCoP 同仁 Daniel Currie Hall、Liisa Duncan、Martin Kohlberger 与 Tim Mills 提供了教学见解与宝贵建议。"},{"en":"Language experts Chantale Cenerini, Rae Anne Claxton, Mary Ann Corbiere, and David Kanatawakhon-Maracle made the conversations in Chapter 9 possible.","zh":"第九章的对话内容得益于语言专家 Chantale Cenerini、Rae Anne Claxton、Mary Ann Corbiere 与 David Kanatawakhon-Maracle 的慷慨与深厚智慧。"},{"en":"Thoughtful reviews and feedback from many colleagues allowed the authors to make substantial improvements to their initial drafts.","zh":"众多同事的认真审阅与反馈，使作者得以对初稿作出大幅改进。"},{"en":"Aileen Lin created artwork, David Wiesblatt recorded the ASL video examples, and Bartłomiej Czaplicki and Deepam Patel created audio.","zh":"Aileen Lin 负责美术设计，David Wiesblatt 录制了美国手语视频示例，Bartłomiej Czaplicki 与 Deepam Patel 制作了音频。"},{"en":"Above all, the authors thank all their linguistics students, past and present, for pushing them toward excellence and justice.","zh":"最重要的是，作者感谢所有过去与现在的语言学学生，是他们促使作者在教学上追求卓越与公正。"}],"terms":[{"en":"Virtual Learning Strategy","zh":"虚拟学习战略","defEn":"An eCampusOntario programme that supported the creation of this open textbook.","defZh":"eCampusOntario 支持本项目等虚拟学习资源建设的资助计划。"},{"en":"TiLCoP","zh":"TiLCoP（作者所在的语言学教师同仁团体）","defEn":"The group of linguistics teachers and researchers to which the authors' colleagues belong.","defZh":"作者的同仁所属的语言学教师与研究者团体，他们为本书提供了教学见解与建议。"},{"en":"American Sign Language (ASL)","zh":"美国手语","defEn":"The sign language used in the video examples recorded for the book.","defZh":"本书配套视频示例中使用的手语，这些示例由 David Wiesblatt 录制。"},{"en":"accessible design","zh":"无障碍设计","defEn":"Design that lets learners with disabilities use the materials fully.","defZh":"指使有障碍的学习者也能充分使用教材内容的设计方式与相关建议。"}],"examples":[],"body":[{"en":"Essentials of Linguistics, 2nd Edition exists because the Government of Ontario funded the project and because eCampusOntario supported it through the Virtual Learning Strategy; readers who want to know more about that strategy can visit the website given in the book. The volume itself is the work of a large team of authors and an even larger team of supporters, whose contributions made the result immeasurably better.","zh":"《语言学基础》第二版之所以能够问世，是因为安大略省政府为本项目提供了资助，并通过 eCampusOntario 的虚拟学习战略给予支持；想进一步了解该战略的读者，可以访问书中给出的网站。这部教材由人数众多的作者团队撰写，而支持者队伍更加庞大，正是他们的贡献使成果好得难以估量。"},{"en":"Colleagues from TiLCoP — Daniel Currie Hall, Liisa Duncan, Martin Kohlberger, and Tim Mills — shared the pedagogical insight and wise counsel drawn from their experience as teachers and researchers of linguistics, and the many conversations with them enriched the work. The conversations in Chapter 9: Reclaiming Indigenous Languages owe their existence to the generosity and deep wisdom of language experts Chantale Cenerini, Rae Anne Claxton, Mary Ann Corbiere, and David Kanatawakhon-Maracle. Thoughtful reviews and feedback from many colleagues also allowed the authors to make substantial improvements to their initial drafts.","zh":"来自 TiLCoP 的同仁 Daniel Currie Hall、Liisa Duncan、Martin Kohlberger 与 Tim Mills 依据其作为语言学教师与研究者的经验，提供了教学见解与明智建议，作者与他们之间的多次交谈使全书内容更加充实。第九章“重拾原住民语言”中的对话，则要归功于语言专家 Chantale Cenerini、Rae Anne Claxton、Mary Ann Corbiere 与 David Kanatawakhon-Maracle 的慷慨与深厚智慧。此外，众多同事的认真审阅与反馈，也使作者得以对初稿作出大幅改进。"},{"en":"Many hands produced the book's supporting materials: Aileen Lin created the artwork, David Wiesblatt recorded the ASL video examples, and Bartłomiej Czaplicki and Deepam Patel created the audio. Bianca James and Tata Ruffle administered the grant funds in McMaster's Department of Linguistics and Languages, and Kate Brown, Accessibility Program Manager at McMaster, advised the team on accessible design. For all this work the authors are grateful. Most of all, however, they thank their linguistics students, past and present, for inspiring them to strive for excellence and justice in teaching linguistics.","zh":"教材的配套材料同样出自许多人之手：Aileen Lin 创作美术作品，David Wiesblatt 录制美国手语视频示例，Bartłomiej Czaplicki 与 Deepam Patel 制作音频。Bianca James 与 Tata Ruffle 在麦克马斯特大学语言学与语言系负责管理资助经费，该校无障碍项目主管 Kate Brown 则就无障碍设计提供了建议。作者对所有这些工作心怀感激。而最令他们感谢的，是过去与现在的语言学学生，正是这些学生激励他们在语言学教学中不断追求卓越与公正。"}]},"front-matter-004-note-to-instructors":{"title":{"en":"A Note to Instructors","zh":"致教师的话"},"summary":{"en":"This note invites instructors to adopt Essentials of Linguistics, 2nd edition as a stand-alone textbook or a supplement for in-person, hybrid, or online courses. It explains the open Creative Commons licensing that permits redistribution, revision, remixing, and retention with attribution, and asks adopters to complete an adoption form and send a brief email.","zh":"本节面向考虑采用《语言学基础》第二版的教师，说明该书既可作为独立教材，也可作为传统教材的补充，适用于面授、混合或线上课程。文中交代了知识共享许可的开放授权，允许在使用者署名来源的前提下再分发、修订、重混与保留书中内容，并请采用者填写采用表并发送一封简短的确认邮件。"},"points":[{"en":"The book works as a stand-alone textbook or as a supplement to a traditional textbook.","zh":"本书既可作为独立教材使用，也可作为传统教材的补充材料。"},{"en":"It suits in-person, hybrid, and online courses alike, since the whole resource is openly licensed.","zh":"由于全部资源采用开放许可，本书同样适用于面授、混合与线上课程。"},{"en":"The Creative Commons licence permits redistribution, revision, remixing and retention, provided the source is attributed.","zh":"知识共享许可允许再分发、修订、重混与保留内容，前提是注明来源出处。"},{"en":"Adopters are asked to fill out an adoption form and email the team to report use.","zh":"采用者需填写采用表，并发送邮件告知使用情况，以便团队掌握使用范围。"}],"terms":[{"en":"Open Educational Resource","zh":"开放教育资源","defEn":"Freely available teaching material that can be reused and adapted by others.","defZh":"可自由获取、允许他人重复使用与改编的教学材料。"},{"en":"Creative Commons Attribution-NonCommercial-ShareAlike 4.0 International License","zh":"知识共享署名—非商业性使用—相同方式共享 4.0 国际许可协议","defEn":"A public licence allowing reuse with attribution, non-commercially, under the same terms.","defZh":"一种公开许可协议，允许在署名、非商业用途并以相同方式共享的条件下重复使用作品。"},{"en":"adoption form","zh":"采用表（教材采用登记表）","defEn":"A short form letting the funder track where the book is used.","defZh":"一份简短的登记表格，用于让资助方追踪教材的使用情况。"}],"examples":[],"body":[{"en":"The note opens by thanking instructors who are considering Essentials of Linguistics, 2nd edition for their linguistics course. The resource is designed so that it can stand alone as a complete textbook or serve as a supplement to a traditional one. Because the material is entirely open, it can be used in an in-person classroom, a hybrid arrangement, or a fully online course without any change in function.","zh":"本节首先感谢正在考虑为语言学课程选用《语言学基础》第二版的教师。该资源的设计目的，是既可以独立充当一部完整教材，也可以作为传统教材的补充。由于全部材料都是开放的，它既能用于面授课堂，也适用于混合教学或完全线上的课程，功能不受授课形式影响。"},{"en":"The open status comes from a Creative Commons Attribution-NonCommercial-ShareAlike 4.0 International License. Under that licence, instructors and others may redistribute, revise, remix, and retain any part of the book, so long as they attribute the source material. The note then makes two simple requests of anyone who adopts the eBook, whether as a required text or an optional supplement: complete the adoption form so the funder can track the book's use, and send an email to teaching.in.linguistics@gmail.com saying where and how it is being used.","zh":"这种开放属性来自知识共享署名—非商业性使用—相同方式共享 4.0 国际许可协议。依据该协议，教师及其他使用者可以再分发、修订、重混并保留书中的任何部分，只需注明来源材料即可。随后，本节对采用这本电子书的读者提出两项简单请求，无论将其作为指定教材还是可选补充材料：一是填写采用表，便于资助方追踪本书的使用情况；二是发送邮件至 teaching.in.linguistics@gmail.com，告知使用地点与方式。团队希望了解使用规模，并计划在未来编写教师资源包，不过该工作目前仍处于很早期的开发阶段。"}]},"front-matter-005-revisions":{"title":{"en":"Revisions","zh":"修订记录"},"summary":{"en":"This page explains how the textbook is revised as a living online resource and where readers of downloadable versions should obtain the current file. It records only major revisions, such as new chapters, sections, videos and exercises, and it states clearly that typos and small clarifications are normally left unrecorded.","zh":"本页说明该教材作为在线资源如何随时更新，并提示使用可下载版本（PDF、EPUB 等）的读者应从主页获取最新文件。页面只记录新增章、节、视频与练习等重大修订，并说明拼写错误、细节澄清等小改动通常不在此登记。"},"points":[{"en":"Because the textbook is online, its content may be updated at any time after initial publication.","zh":"由于教材是在线资源，其内容在初次发布之后可能随时更新。"},{"en":"Users of PDF, EPUB and other downloadable versions are advised to download the latest file from the home page.","zh":"使用 PDF、EPUB 等可下载版本的读者，建议从主页重新下载最新文件。"},{"en":"Only major revisions such as new chapters, sections, videos and exercises are recorded on this page.","zh":"本页只登记新章、新节、新视频、新练习等重大修订。"},{"en":"Smaller changes, including typos and minor clarification or re-wording, are not normally listed.","zh":"拼写错误以及小幅澄清、改写等较小改动通常不予列出。"},{"en":"The revision list runs from Version 2.0 in March 2022 to Version 2.5 in February 2026.","zh":"修订列表从 2022 年 3 月的 2.0 版一直记录到 2026 年 2 月的 2.5 版。"}],"terms":[],"examples":[{"text":"Version 2.5 February 2026, added sections 1.7 and 1.8","noteEn":"The newest entry records two new sections added in February 2026.","noteZh":"最新一条记录显示 2026 年 2 月新增了 1.7 与 1.8 两节。"},{"text":"Version 2.3: 11 July 2023, added portions of Chapter 14","noteEn":"A major revision may add only part of a chapter rather than a complete one.","noteZh":"重大修订也可能只增补某一章的部分内容，而非整章。"},{"text":"Version 2.0: 1 March 2022, initial release of Chapters 1–11 and portions of Chapter 13","noteEn":"The first release contained most chapters but only portions of Chapter 13.","noteZh":"首个版本收录了大部分章，而第 13 章只发布了部分内容。"}],"body":[{"en":"This textbook is designed as an online resource, so its contents can be modified at any moment rather than being frozen at publication. Readers who work with a downloadable copy are therefore encouraged to return to the home page and take the most recent file; the page notes that it was most recently updated on 28 March 2026.","zh":"本教材按在线资源设计，内容不会在出版时固定下来，而是可以随时修改。因此，使用可下载副本的读者最好回到主页获取最新文件；页面注明最近一次更新是在 2026 年 3 月 28 日。"},{"en":"Major revisions are gathered on this page. They include new chapters or sections, new videos, new exercises, and similar structural additions that change how the book can be used. Each entry gives a version number, a date or date range, and a short description of what was added or updated.","zh":"重大修订汇总在本页。它们包括新增的章或节、新视频、新练习，以及诸如此类改变教材使用方式的结构性增补。每条记录都给出一个版本号、日期或日期区间，并简要说明增补或更新的内容。"},{"en":"Smaller revisions are treated differently. Typos, minor clarifications and small re-wordings are made when needed but are not normally listed here, so a lack of entries does not mean the text has stood still. The recorded history begins with Version 2.0, released on 1 March 2022, which contained Chapters 1–11 and portions of Chapter 13.","zh":"较小的修订另有处理方式。拼写错误、细节澄清和轻微改写会在需要时进行，但通常不在此列出，因此没有记录并不意味着教材停滞不变。换言之，在线正文会持续被修订，只有影响较大的变动才被登记，而登记的重点是变动的事实、时间与版本编号。有记录的修订史始于 2022 年 3 月 1 日发布的 2.0 版，该版包含第 1–11 章以及第 13 章的部分内容。"},{"en":"Later versions show how the book grew. Chapter 12 arrived in Version 2.2 in August 2022, Appendix 1 in Version 2.1 in July 2022, portions of Chapter 14 in Version 2.3 in July 2023, and updated or added videos for sections 3.1, 3.2, 10.1 and 10.2 across Versions 2.4 and 2.5.","zh":"此后的版本展示了教材的扩充过程。第 12 章随 2022 年 8 月的 2.2 版加入，附录 1 随 2022 年 7 月的 2.1 版加入，第 14 章的部分内容随 2023 年 7 月的 2.3 版加入；3.1、3.2、10.1、10.2 各节的视频则在 2.4 与 2.5 版中更新或新增。"}]},"part-001-chapter-1-language-science":{"title":{"en":"Chapter 1: Human Language and Language Science","zh":"第 1 章：人类语言与语言科学"},"summary":{"en":"This opening chapter introduces language as an object of scientific study rather than a set of rules that can be marked right or wrong. It explains that linguists use linguistic tools and techniques to observe patterns in human languages and to draw conclusions about abstract principles in minds and communities. It also asks how language science and language attitudes have bolstered colonial power and privilege.","zh":"本章引导读者把语言视为科学研究的对象，而不是一套可以判对错的规则。语言学家运用语言学的工具与技术观察人类各种语言中的模式，并据此对人类语言在人脑与语言社群中的抽象原则和组织方式作出推论。本章同时反思语言科学以及人们的语言态度如何支撑殖民性的权力与特权。"},"points":[{"en":"The chapter treats language as something to observe scientifically, not as rules you can get right or wrong.","zh":"本章把语言当作科学观察的对象，而不是可以判对错的规则。"},{"en":"Linguists use the tools and techniques of linguistics to observe patterns across human languages.","zh":"语言学家运用语言学的工具与技术，观察人类各种语言中的模式。"},{"en":"Observations support conclusions about the abstract principles and organization of language in minds and communities.","zh":"这些观察支持我们对语言在人脑与语言社群中的抽象原则与组织方式作出结论。"},{"en":"The chapter also asks how language science and language attitudes have bolstered colonial structures of power and privilege.","zh":"本章还追问语言科学与语言态度如何支撑了殖民性的权力与特权结构。"},{"en":"Objectives cover prescriptive versus descriptive thinking, mental grammar, universal properties, methods and ethics.","zh":"学习目标包括规定性与描述性思维、心理语法、语言的普遍属性、研究方法与研究伦理。"}],"terms":[{"en":"prescriptive","zh":"规定性","defEn":"Approaching language by stating how it ought to be used, with rules that can be right or wrong.","defZh":"以规则说明语言应当如何使用，并据此判断正确与错误的研究取向。"},{"en":"descriptive","zh":"描述性","defEn":"Approaching language by observing and describing how people actually use it.","defZh":"通过观察与描写，说明人们实际上如何使用语言，而不作对错评判的研究取向。"},{"en":"mental grammar","zh":"心理语法","defEn":"The shared system in people's minds that allows them to understand one another.","defZh":"存在于人脑中的共享系统，使同一语言的使用者能够相互理解、彼此交流。"}],"examples":[],"body":[{"en":"The chapter begins the book by asking what language is and how language scientists, also known as linguists, think about it and observe it. Many readers come to the study of language expecting an approach built on rules that can be marked right or wrong. This book takes a different path: it shows how the tools and techniques of linguistics can be used to observe the patterns of human languages.","zh":"本章开篇追问语言是什么，以及语言科学家（即语言学家）如何看待和观察语言。许多读者此前接触语言学习时，面对的都是可以判对错的规则，而本书不走这条路：它展示如何用语言学的工具与技术观察人类各种语言中的模式。"},{"en":"From those observations the book tries to draw conclusions about the abstract principles and organization of human language in people's minds and in language communities. Along the way it also considers how language science and people's attitudes about language have bolstered colonial structures of power and privilege and have been used to do harm, so the study of language is presented as a scientific and an ethical project at once.","zh":"从这些观察出发，本书试图就人类语言在人脑与语言社群中的抽象原则和组织方式得出结论。行文之中，本书也考察语言科学以及人们对语言的态度如何支撑了殖民性的权力与特权结构，并被用来造成伤害；因此语言研究既是科学课题，也是伦理课题。"},{"en":"By the end of the chapter, readers should be able to differentiate between prescriptive and descriptive ways of thinking about language, identify components of mental grammar, explain some properties of all human languages, describe some techniques for doing language science, and discuss the ethics of doing language science.","zh":"学完本章，读者应能区分规定性与描述性的语言思维方式、识别心理语法的组成部分、解释人类语言的某些共同属性、描述从事语言科学的若干方法，并讨论从事语言科学的伦理问题。"}]},"chapter-001-slug-1-1-what-even-is-language":{"title":{"en":"1.1 What even is language?","zh":"1.1 语言究竟是什么？"},"summary":{"en":"Linguistics is the scientific study of human language, and the word language names several interconnected notions, from individual signed and spoken languages to computer languages and metaphors. Knowing a language means sharing a mental grammar. The section outlines the modality, mental lexicon, articulatory phonetics, phonology, syntax, semantics and pragmatics of that grammar, and explains why reading and writing are secondary parts of it.","zh":"语言学是对人类语言的科学研究，而 language 一词指称若干彼此关联的概念，从具体的有声语言与手语，到计算机语言和比喻用法。掌握一门语言意味着共享一套心理语法。本节依次说明语法中的模态、心理词库、发音语音学、音系学、句法学、语义学和语用学，并解释为何读和写只是心理语法的次要部分。"},"points":[{"en":"Linguistics is the scientific study of human language, and language names several interconnected concepts.","zh":"语言学是对人类语言的科学研究，而语言一词指称若干彼此关联的概念。"},{"en":"Languages may be signed or vocalized; modality describes which channel a language uses.","zh":"语言可以是有声的，也可以是手语的；模态指语言使用哪一种传递渠道。"},{"en":"The mental lexicon links forms with meanings, and most form-meaning links are arbitrary.","zh":"心理词库把形式与意义联系起来，而多数词的形式与意义的联系是任意的。"},{"en":"Much grammatical knowledge, including phonology and syntax, is implicit and therefore hard to observe.","zh":"包括音系学和句法学在内的许多语法知识是隐性的，因而难以直接观察。"},{"en":"Reading and writing are secondary parts of the mental grammar, since literacy is not needed for competence.","zh":"读和写是心理语法的次要部分，因为语法能力并不以识字为前提。"}],"terms":[{"en":"mental grammar","zh":"心理语法","defEn":"The shared system in language users' minds that lets them understand each other.","defZh":"语言使用者心智中的共享系统，使他们能够相互理解、交流想法。"},{"en":"modality","zh":"模态","defEn":"The channel through which a language is produced and received, signed or vocalized.","defZh":"语言产生与接收所依托的渠道，分为有声语言与手语两大类。"},{"en":"mental lexicon","zh":"心理词库","defEn":"The part of the grammar that pairs the forms of words with their meanings.","defZh":"语法中把词的形式与意义配对的部分，犹如每个人心中的一部词典。"},{"en":"articulatory phonetics","zh":"发音语音学","defEn":"The study of how language users control the muscles that produce speech sounds or signs.","defZh":"研究语言使用者如何控制肌肉以发出语音或做出手语动作。"},{"en":"arbitrary","zh":"任意性","defEn":"Describing a form-meaning link that is not motivated by the meaning itself.","defZh":"指形式与意义的联系并非由意义本身决定，而是约定俗成的。"},{"en":"phonology","zh":"音系学","defEn":"Knowledge of how the physical units of language combine and change in context.","defZh":"关于语言的物理单位如何组合、又在不同语境中如何变化的知识。"}],"examples":[{"text":"pumpkin, kosmaan","noteEn":"English and Nishnaabemwin name the same vegetable with forms arbitrarily paired with its meaning.","noteZh":"英语与尼什纳贝姆温语（Nishnaabemwin）用这两个形式指称同一种蔬菜，形式与意义之间并无自然联系。"},{"text":"cookies, with a z sound at the end","noteEn":"The z sound at the end of cookies signals that more than one cookie is being offered.","noteZh":"cookies 末尾的 z 音表示所给的不止一块饼干，这属于形态学知识。"},{"text":"“I have some news,”","noteEn":"The same sentence can be taken as good news or bad news depending on the context.","noteZh":"同一句话在不同语境中既可理解为好消息，也可理解为坏消息，这是语用学所管的意义。"},{"text":"the Cyrillic alphabet and traditional Mongolian script","noteEn":"Speakers understand each other whichever script records their language, so writing is secondary.","noteZh":"无论用哪种文字记录，蒙古语使用者都能相互听懂，说明文字系统只是心理语法的次要部分。"}],"body":[{"en":"Language is something every reader already uses, yet the word names several connected notions. It can refer to individual languages such as American Sign Language (ASL), Basque, English, Langue des signes québecoise (LSQ), Nishnaabemwin or Xhosa. It also covers computer languages like Python, R, C++ or Perl, and metaphorical uses such as body language or love languages, which linguistics normally sets aside. Linguistics itself is the scientific study of human language.","zh":"语言是每位读者都在使用的东西，但这一名称指称若干彼此关联的概念。它既可以指一门门具体的语言，如美国手语（ASL）、巴斯克语、英语、魁北克手语（LSQ）、尼什纳贝姆温语、科萨语，也常用来指 Python、R、C++、Perl 等计算机语言，以及身势语、爱之语之类的比喻用法，而后者通常不在语言学的考察范围之内。语言学则是对人类语言进行的科学研究。"},{"en":"To know a language you first need its modality: it may be signed or vocalized, with information received by ear, eye or touch. Next you segment the stream of sounds or gestures into meaningful units, which is the work of the mental lexicon, where forms pair with meanings. For most words in the world's languages that pairing is arbitrary, though some forms are iconic. Producing a word also requires articulatory phonetics, control of the muscles that make the sounds or signs.","zh":"认识一种语言，首先要弄清它的模态：语言可能是有声的，也可能是手语的，信息分别由耳朵、眼睛或触觉接收。接着要把连续的声音或手势切分为有意义的单位，这正是心理词库的工作——它把形式与意义配对。世界上大多数语言的词，其形式与意义的联系是任意的，只有少数形式具有象似性。要说出一个词，还需要发音语音学的知识，即控制发音器官或手部动作的能力。"},{"en":"Much of this grammatical knowledge is implicit. You may be fairly conscious of your lexicon and of some morphology, but you are probably not conscious of how you use your articulators to make k or z. Implicit knowledge also includes phonology, how physical units combine and change in context, and syntax, which knows how words combine into phrases and sentences. Syntax works with semantics to calculate meanings, and pragmatics handles meanings that arise in context.","zh":"这些语法知识中有许多是隐性的。你也许能明确意识到自己的词库以及部分形态学知识，例如懂得 cookies 末尾的 z 表示不止一块饼干，但对如何用发音器官发出 k 或 z 这样的音却往往并不自觉。隐性知识还包括音系学，即语言的物理单位如何组合、在不同语境中如何变化；以及句法学，即词如何组成短语和句子。句法学与语义学共同计算出短语的意义，语用学则说明不同语境中产生的意义。"},{"en":"Reading and writing are not central to this picture, because language users do not need literacy to have a mental grammar. Children in Canada commonly start learning to read and write around age five, yet they are competent in the phonetics, phonology, morphology, syntax and semantics of one or more languages before they go to school. Mongolian currently uses two writing systems, the Cyrillic alphabet and the traditional vertical script, and speakers understand each other either way; signed languages like ASL and LSQ have no written forms at all.","zh":"读和写并未进入心理语法的核心，因为语言使用者不需要会读写才拥有心理语法。加拿大儿童通常约五岁才开始学习读写，但在入学之前就已经相当熟练地掌握了一门或多门语言的语音、音系、形态、句法和语义。蒙古语目前同时使用西里尔字母和传统蒙古文两种文字系统，无论用哪种文字记录，使用者都能相互听懂；美国手语和魁北克手语等手语则根本没有书面形式。有文化素养的人，读写当然融入其语法之中，但它并不是语法能力的必要条件。"}]},"chapter-002-slug-1-2-what-grammars-are-and-arent":{"title":{"en":"1.2 What grammars are and aren't","zh":"1.2 语法是什么，不是什么"},"summary":{"en":"This section contrasts the mental grammar with grammar books and style guides. Every human language has a mental grammar, so the claim that a language has no grammar is false and often serves racist, colonialist or ableist ideas. No grammar is better than another, even though people attach social value to varieties. Grammar is also creative, or productive, which explains why languages always change.","zh":"本节把心理语法与语法书、写作规范区分开来。每一种人类语言都有心理语法，因此声称某门语言“没有语法”是错误的，这种说法常常服务于种族主义、殖民主义或健全主义观念。尽管人们会给语言变体附加社会价值，但没有哪种语法比别的更好。语法还具有创造性，也就是能产性，这正是语言始终变化的原因。"},"points":[{"en":"The book studies the mental grammar, the system that lets users of a language understand one another.","zh":"本书研究的是心理语法，即让同一语言的使用者相互理解的系统。"},{"en":"All languages have grammar, and saying a language has none often expresses racist, colonialist or ableist ideas.","zh":"所有语言都有语法，声称某语言没有语法往往是在表达种族主义、殖民主义或健全主义观念。"},{"en":"No grammar is better than another, although people do use social judgments to build hierarchies of power.","zh":"没有哪种语法优于其他语法，尽管人们确实用社会评价建构权力等级。"},{"en":"Productivity or generativity means a finite vocabulary and finite principles yield infinite new sentences.","zh":"能产性（生成性）指有限的词汇与有限的原则可以生成无限多的新句子。"},{"en":"Because grammar is productive, languages always change, even when institutes try to fix their rules.","zh":"由于语法具有能产性，语言始终在变化，即使官方机构试图规定其规则。"}],"terms":[{"en":"mental grammar","zh":"心理语法","defEn":"The system in your mind that lets you understand others who share your language.","defZh":"你心智中的系统，使你能够理解同样掌握这门语言的其他人。"},{"en":"productivity","zh":"能产性","defEn":"The property of producing infinitely many new words and sentences from finite resources.","defZh":"用有限的词汇与有限的组合原则，产出无限多新词和新句的属性。"},{"en":"generativity","zh":"生成性","defEn":"A synonym for productivity: the capacity to generate ever new expressions in a language.","defZh":"与能产性同义，指语言能够不断生成前所未有的新词与新句的能力。"},{"en":"dialect","zh":"方言","defEn":"A regional or social variety of a language, linguistically as valid as any other.","defZh":"某语言的地域或社会变体，从语言学看与其他变体同样有效。"},{"en":"variety","zh":"语言变体","defEn":"A particular form of a language used by a group or in a setting.","defZh":"某一特定群体或某一场合中所使用的语言的具体形式，如各种方言。"},{"en":"lexicon","zh":"词库","defEn":"A language's vocabulary, where new words for new concepts first show up.","defZh":"一种语言的词汇总汇，为新概念创造的新词最容易在此显现。"}],"examples":[{"text":"the verb google","noteEn":"A new verb entered the lexicon for a new concept and is now used nearly every day.","noteZh":"动词 google 因新概念进入词库，如今几乎每天都被使用，显示词汇层面的语言变化。"},{"text":"“Oh, I don’t speak real Italian, just a dialect.”","noteEn":"The speaker treats a dialect as inferior to so-called real Italian, a social rather than linguistic judgment.","noteZh":"说话人把方言看得不如所谓“真正的意大利语”，这是社会评价而非语言学结论。"},{"text":"“Québec French is just sloppy; it’s not as good as the French they speak in France.”","noteEn":"Linguists reject such rankings: no variety is linguistically better or worse than another.","noteZh":"语言学家不接受这类排序：任何语言变体在语言学上都不分优劣。"},{"text":"“Kids these days are ruining English!”","noteEn":"This complaint has accompanied language change throughout history and is repeated in every generation.","noteZh":"这类抱怨伴随语言变化自古就有，每一代人都重复类似的指责。"}],"body":[{"en":"The grammar this book cares about is not the textbook or style guide full of rules that bring penalties when broken. It is the mental grammar, the system in your mind that lets you understand and be understood by others who know your language. Every human language has one. Claims that a language has no grammar are simply false, and they are one way that people express racist, colonialist and ableist ideas.","zh":"本书所说的语法，与满是规则、违反就要受罚的语法书或写作规范不同。它指的是心理语法，即你心智中的系统，使你能够理解别人，也被懂得这门语言的人理解。每一种人类语言都有心理语法。声称某门语言“没有语法”是完全错误的，这种说法正是人们表达种族主义、殖民主义和健全主义观念的一种方式。"},{"en":"All languages have a system for forming words, a way of organizing words into sentences, and a systematic way of assigning meanings. Even languages without alphabets, dictionaries or published books of rules have users who understand each other, so linguists can study those shared grammars with scientific techniques. No grammar is better than another either: the idea that a dialect, Québec French, Newfoundland English or Texan English is inferior is a social judgment, not a linguistic finding. Scientists do not rank what they study, yet many people, including linguists, do attribute value to varieties and reinforce hierarchies of power and status.","zh":"所有语言都有构词系统、把词组织成句子的方式，以及系统地指派意义的办法；即使没有字母表、词典或成文规则，使用者仍能相互理解，语言学家因此可以借助科学方法研究这些共享的语法。同时，没有哪种语法比别的更好：说某种方言、魁北克法语、纽芬兰英语或得克萨斯英语低劣，都是社会评价而非语言学结论。科学家不会给自己研究的对象排名，但现实中许多人（包括语言学家）确实会给语言变体赋予价值，并强化权力与地位的等级。"},{"en":"Creativity, better called productivity or generativity, is one of the most fundamental properties of grammar. Every language has a finite vocabulary and a finite set of combining principles, yet it can produce an infinite number of possible new words and sentences. A consequence is that languages always change. Older people have always complained that younger people are ruining the language, and some countries have official institutes that rule on which words and structures are permitted, but change is inevitable as speakers and societies change. Lexical change is easy to observe, as with the verb google, and phonetics, phonology, syntax, morphology and semantics change too.","zh":"语法最根本的属性之一是创造性，更准确的叫法是能产性或生成性。每种语言的词汇量都有限，组合词的原则也有限，却能产出无限多的可能新词和新句。由此产生的后果是语言始终在变化。自古以来，年长者就抱怨年轻人毁掉了语言；法国、德国等国甚至设有官方机构，规定哪些词和句式允许使用。但随着使用者和社会发生变化，语言的变化不可避免。词汇层面的变化最容易观察，例如动词 google；语音、音系、句法、形态和语义同样都在变化。"}]},"chapter-003-slug-1-3-studying-language-scientifically":{"title":{"en":"1.3 Studying language scientifically","zh":"1.3 科学地研究语言"},"summary":{"en":"Linguistics studies human language through systematic, empirical observation rather than laboratory equipment, and it aims to describe language as it is used instead of prescribing it. Because much of our grammatical knowledge is unconscious, linguists use tools such as metalinguistic awareness, acceptability judgments, surveys, corpora and experiments to observe the mind indirectly.","zh":"语言学以系统、经验性的观察研究人类语言，并不需要实验室设备；其目标是描写语言，而不是规定语言应该怎样使用。由于语法知识大多处于无意识状态，语言学家借助元语言意识、可接受性判断、问卷调查、语料库和实验等工具，间接地观察心智中的语法。"},"points":[{"en":"Linguistics asks questions about language using a scientific approach based on systematic, empirical observation.","zh":"语言学以科学的提问方式研究语言，其基础是系统而经验性的观察。"},{"en":"Empirical means observing data as evidence, and linguists describe language rather than prescribing how it should be used.","zh":"经验性指以观察到的数据作为证据；语言学家描写语言，而不规定语言应当如何使用。"},{"en":"Metalinguistic awareness is conscious knowledge about grammar, which is often easier to access in a learned language.","zh":"元语言意识是关于语法的有意识知识，对于后天学习的语言往往更容易提取。"},{"en":"Acceptability judgments reveal that grammaticality concerns whether a form could exist, not whether it does.","zh":"可接受性判断表明，合乎语法性关注的是某一形式能否存在，而不是它是否已经存在。"},{"en":"Surveys, corpora, phonetic software and psychological experiments let linguists observe language systematically.","zh":"问卷调查、语料库、语音分析软件与心理学实验使语言学家能够系统地观察语言。"}],"terms":[{"en":"empirical","zh":"经验性的","defEn":"Based on data observed in the world rather than on intuition or authority.","defZh":"以在现实世界中观察到的数据为依据，而非凭直觉或权威论断。"},{"en":"descriptive approach","zh":"描写性取向","defEn":"An approach that describes what people actually do with their language.","defZh":"描写人们实际如何使用语言的研究取向，不对用法作好坏评判。"},{"en":"prescriptive approach","zh":"规定性取向","defEn":"An approach that tells people how they should or should not use language.","defZh":"规定人们应当或不应当如何使用语言的取向，常带有评判色彩。"},{"en":"metalinguistic awareness","zh":"元语言意识","defEn":"Conscious knowledge about your grammar, as opposed to the grammatical knowledge itself.","defZh":"对自己语法的有意识知识，与语法知识本身相对，常用于间接考察心理语法。"},{"en":"acceptability judgment","zh":"可接受性判断","defEn":"A speaker's judgment about whether a form is possible in their language.","defZh":"说话人对某一形式在其语言中是否成立所作出的判断，又称合乎语法性判断。"},{"en":"corpus","zh":"语料库","defEn":"A large database collecting examples of language as used in the world.","defZh":"大规模汇集现实语言使用实例的数据库，可包含文本、音频或手语视频。"}],"examples":[{"text":"Are you going to call your cute little creature a blifter or a lbitfer?","noteEn":"Both forms use English sounds, but only blifter feels like a possible word.","noteZh":"两个形式都由英语语音构成，但只有 blifter 让人感觉可能成为英语词。"},{"text":"What did Sam compare the forged painting with?","noteEn":"This wh-question is acceptable in English, unlike the version with and.","noteZh":"这个特殊疑问句在英语中可以接受，而用 and 构成的版本则不行。"},{"text":"*What did Sam compare the forged painting and?","noteEn":"The asterisk at the beginning marks a form that simply cannot happen.","noteZh":"句首的星号标记出这一形式在英语中根本无法成立，属于不合语法。"},{"text":"people in Saskatchewan call it a bunny hug","noteEn":"Survey data reveal regional words for the same garment, a hoodie or sweatshirt.","noteZh":"调查数据显示，同一件连帽衫在加拿大不同地区有不同的说法。"}],"body":[{"en":"Linguistics is the science of human language, but doing linguistics does not require a lab coat and a microscope; it means asking questions about language scientifically, through systematic and empirical observation. Empirical means observing data to find evidence for our theories, just as entomologists observe insects and chemists observe substances. Linguists aim for accurate description rather than value judgments, so the goal is a descriptive approach, not a prescriptive one. Saying that adding -s to a noun lets it refer to many things, as in apples, books, or shoes, is descriptive; insisting on viri rather than viruses is prescriptive.","zh":"语言学是研究人类语言的科学，但这并不意味着做语言学需要白大褂和显微镜，而是指以科学的方式提问，进行系统而经验性的观察。经验性就是以观察到的数据为理论寻找证据：昆虫学家观察昆虫，化学家观察物质，语言学家则观察人们如何使用语言。语言学家追求准确的描写而非价值评判，因此目标是描写性取向，而不是规定性取向。说英语名词加上 -s 就能指称多个事物，如 apples、books、shoes，这是描写；坚称 virus 必须复数化为 viri，则是规定。"},{"en":"Much of what we study is hard to observe: we cannot go out to the garden and find grammar crawling on a plant, so we must work out how to observe the mind. One tool is metalinguistic awareness, the conscious knowledge you have about your grammar rather than the grammatical knowledge itself; for a first language much of it is implicit and hard to access. Consider naming a creature in a game: both blifter and lbitfer use English sounds and neither exists, yet only blifter could be a word. Since lbitfer is not a possible English word, it is ungrammatical; grammaticality is about whether a form could exist, not about what already exists.","zh":"难点在于，我们研究的许多对象难以直接观察：我们无法走到花园里，找到一只趴在植物上的语法，因此必须想办法观察心智。工具之一是元语言意识，即你对自己语法所具有的有意识知识，而不是语法知识本身；第一语言的大量此类知识是隐性的，不易提取。设想给游戏中的小生物起名：blifter 和 lbitfer 都由英语语音构成，且都不存在于英语中，但只有 blifter 可能成为词。既然 lbitfer 不可能是英语词，它在英语中就是不合语法的；合乎语法性关乎某一形式能否存在，而非它是否已经存在。"},{"en":"Acceptability judgments, also called grammaticality judgments, are our empirical observations. Sam compared the forged painting with the original and the version with and are both acceptable, and both make yes-no questions, yet only What did Sam compare the forged painting with? works as a wh-question; *What did Sam compare the forged painting and? cannot happen. Our job is to explain what in the mental grammar accounts for the difference. Other tools include surveys, which reveal regional words such as sweatshirt, hoodie and, in Saskatchewan, bunny hug; corpora; software such as Praat, ELAN and SLP-Annotator; and experiments measuring reaction times, eye movements, or brain activity with EEG and fMRI.","zh":"可接受性判断（又称合乎语法性判断）就是我们的经验性观察。Sam compared the forged painting with the original 与用 and 的版本都可以接受，也都能构成一般疑问句，但只有 What did Sam compare the forged painting with? 能作为特殊疑问句成立；*What did Sam compare the forged painting and? 根本不可能。接下来我们的任务，就是解释心理语法中的什么因素造成了这种差异。其他工具还包括：问卷调查，可揭示 sweatshirt、hoodie 以及在萨斯喀彻温省说的 bunny hug 等地区用词；语料库；Praat、ELAN、SLP-Annotator 等软件；以及测量反应时、眼动，或用脑电图（EEG）与功能性磁共振成像（fMRI）观察脑活动的实验。"}]},"chapter-004-slug-1-4-thinking-about-standards-and-proper-grammar":{"title":{"en":"1.4 Thinking about standards and “proper” grammar","zh":"1.4 关于标准语与「规范」语法的思考"},"summary":{"en":"Linguists aim to treat all languages and dialects as equally valid, yet social power relations generate linguistic bias, including among linguists themselves. The standard variety of a language is not objectively best; it is the variety linked to economic, social or political power, and treating it as the only correct form discriminates against speakers of other varieties.","zh":"语言学家的目标是同等看待一切语言与方言，但社会权力关系会催生语言偏见，语言学家自身也不例外。所谓标准变体并非客观上最优，而是与经济社会或政治权力相联系的变体；若把它当作唯一正确形式，就会歧视使用其他变体的人，例如克里奥尔语与黑人英语的使用者。"},"points":[{"en":"Studying language scientifically means not ranking any dialect as better than another, a genuinely radical goal.","zh":"科学地研究语言意味着不把任何方言评判为优于其他方言，这是一个颇为激进的目标。"},{"en":"Relationships such as teacher-student and communities of ethnicity, religion or profession shape language expectations.","zh":"师生、医患等关系，以及族群、宗教、职业等社群身份，都会塑造人们对语言的期待。"},{"en":"North Americans often perceive all British English varieties as prestigious, even those stigmatized in the UK.","zh":"北美听众常把所有英国英语变体都视为高声望，即便其中一些在英国本土受到污名化。"},{"en":"Standardization happens through social mechanisms of power, such as official academies, dictionaries and style guides.","zh":"标准化通过社会权力机制实现，例如官方机构、词典与体例指南。"},{"en":"Judging the standard as the only proper form discriminates against Kreyòl speakers, Black English speakers and others.","zh":"把标准语视为唯一正确形式，会歧视克里奥尔语使用者、黑人英语使用者等人群。"}],"terms":[{"en":"linguistic bias","zh":"语言偏见","defEn":"A positive or negative judgment about people based on how they use language.","defZh":"依据他人使用语言的方式对其作出的正面或负面评判，人人皆难以避免。"},{"en":"standard variety","zh":"标准变体","defEn":"The form that most closely matches dictionaries, textbooks and high-status media.","defZh":"与词典、教科书及高地位媒体所用形式最为接近的语言变体。"},{"en":"standardization","zh":"标准化","defEn":"The process by which one variety is established as the norm through social power.","defZh":"通过社会权力把某一变体确立为规范的过程，与语法优劣无关。"},{"en":"prestige","zh":"声望","defEn":"The social value attached to a way of speaking, making it seem more educated.","defZh":"附着于某种说话方式之上的社会价值，使人显得更有教养或更聪明。"},{"en":"Black English","zh":"黑人英语","defEn":"The English variety associated with Black speakers, also called AAL or AAVE.","defZh":"与黑人说话者相联系的英语变体，也称非洲裔美国人语言或非洲裔美国人白话英语。"}],"examples":[{"text":"un péril mortel","noteEn":"The Académie Française called inclusive writing a mortal danger to French.","noteZh":"法兰西学术院把包容性写法称为法语面临的「致命危险」。"},{"text":"the Queen’s English","noteEn":"The British shorthand for the highest-prestige variety points to royal power.","noteZh":"英国指称最高声望变体的简称「女王英语」，直接指向王权。"},{"text":"More than 90% of people Haiti speak Kreyòl, a language with its own consistent grammar and spelling.","noteEn":"Haitian schooling in standardized French tells children their own language is wrong.","noteZh":"海地学校以标准法语授课，等于告诉孩子他们自己的语言是错的。"},{"text":"he distrusted the doctor’s medical opinion because his accent was not Canadian","noteEn":"An Alberta judge set aside medical evidence on the basis of accent.","noteZh":"艾伯塔省一名法官仅凭口音便否决了医生提供的医学证据。"}],"body":[{"en":"Linguists aim to describe languages and dialects accurately without ranking any dialect as better than another. This is a radical goal, because language is intertwined with human relationships and social categories: the communities we belong to, whether based on ethnicity, religion or profession, shape how we use language and expect others to use it, and relationships like teacher-student or doctor-patient involve power relations that shape expectations about language. Everyone, including linguists, has linguistic biases arising from social power dynamics, but learning about language and power gives us metalinguistic awareness of them.","zh":"语言学家的目标是准确描写各种语言与方言，而不把任何方言评判为优于其他方言。这是一个颇为激进的目标，因为语言与人的关系和社会范畴紧密交织：我们所属的社群——无论基于族群、宗教还是职业——都会塑造我们使用语言的方式和对他人的期待；师生、医患之类的关系也包含影响语言期待的权力关系。包括语言学家在内，人人都有源自社会权力关系的语言偏见，但了解语言与权力可以帮助我们对这些偏见形成元语言意识。"},{"en":"One prevalent bias in Canada and the US is that North Americans tend to perceive all varieties of British English as having high prestige, assuming that speakers of UK English are better educated, even for varieties that have low prestige in the United Kingdom. The standard variety is the form that has been standardized, matching dictionaries, textbooks and high-status media. In France the Académie Française decides what counts as correct French, declaring inclusive writing un péril mortel, a mortal danger. English has no official language police, but standardized English is enforced through social norms, dictionaries, style guides and grammar-checking software.","zh":"在加拿大和美国，一种很普遍的语言偏见是把所有英国英语变体都视为具有高声望，认为其使用者受教育更好，即使某些变体在英国本土声望很低。标准变体指的是已经标准化的形式，即与词典、教科书和高地位媒体最为一致的形式。在法国，法兰西学术院决定什么算正确的法语，并宣称包容性写法是 un péril mortel（致命危险）。英语没有官方的语言警察，但标准英语仍通过社会规范、词典、体例指南和语法检查软件得以推行。"},{"en":"The standardized variety is not objectively the best or clearest; nothing linguistic determines what is best. It is usually the variety associated with economic, social or political power, and for English and other European languages it tends to be the variety used by white people with a certain amount of formal education. Black English makes this visible: not all Black people in the United States speak it, and not all its speakers are Black, but using it is a strong indicator of Black American identity, yet it is not what anyone means by Standard American English. When people say standard language they usually think the language that white people use, and treating that standard as the only correct form discriminates against other varieties.","zh":"标准变体并不是客观上最好或最清晰的；语言上没有任何东西能判定何者「最好」。它通常是与经济、社会或政治权力相联系的变体；对英语及其他欧洲语言而言，它往往是接受过一定正规教育的白人使用的变体。黑人英语正说明了这一点：美国并非所有黑人都说黑人英语，其使用者也并非都是黑人，但使用它仍是黑人美国人身份的有力标志，然而它并不属于任何人所说的「标准美国英语」。人们说「标准语言」时，想到的通常是「白人使用的语言」；把这样的标准当作唯一正确形式，就会歧视其他变体。"}]},"chapter-005-slug-1-5-doing-harm-with-language-science":{"title":{"en":"1.5 Doing harm with language science","zh":"1.5 语言科学造成的伤害"},"summary":{"en":"Science is not inherently virtuous, and the tools of linguistics have caused real harm. Missionary documentation of Indigenous languages was shaped by a European viewpoint and contributed to language loss, while residential schools violently suppressed those languages. Modern linguistics can also harm communities through extractive research practices, prescriptive fallout and the pathologizing of disabled people’s language.","zh":"科学本身并不天然高尚，语言学的工具也曾造成真实伤害。传教士对原住民语言的记录带着欧洲视角，并助长了语言流失，寄宿学校更以暴力压制这些语言。现代语言学也可能通过掠夺式研究、描写滑向规定，以及把残障者的语言病理化而伤害相关社群。"},"points":[{"en":"Much foundational linguistic work was done by missionaries aiming to convert people rather than to discover mental grammar.","zh":"语言学许多奠基性工作由传教士完成，其目标是使人皈依，而非揭示心理语法。"},{"en":"Missionaries wrote Indigenous languages with the Roman alphabet and European assumptions, producing inaccurate documents.","zh":"传教士用罗马字母和欧洲语言的假设记录原住民语言，所留下的文献并不准确。"},{"en":"Written texts froze particular forms and pushed aside variation, causing many language features to fall out of use.","zh":"书面文本固化了特定形式、排斥了变异，导致许多语言特征不再使用。"},{"en":"Residential schools separated children from families and forbade their languages, so English or French became survival.","zh":"寄宿学校使儿童与家庭分离并禁止他们说本族语言，说英语或法语成了生存手段。"},{"en":"Linguists may extract data, publish sacred or private material, or turn descriptions into new prescriptive standards.","zh":"语言学家可能只取走数据、发表神圣或隐私材料，或把描写变成新的规定性标准。"},{"en":"Oralism deprives deaf children of input, and norms of language use make differences look like disorders.","zh":"口语主义剥夺了聋童的语言输入，而语言使用规范则把差异误认为障碍。"}],"terms":[{"en":"missionary linguistics","zh":"传教士语言学","defEn":"Early documentation of Indigenous languages by Christian missionaries with religious and commercial goals.","defZh":"基督教传教士出于传教与贸易等目的对原住民语言所作的早期记录工作。"},{"en":"residential schools","zh":"寄宿学校","defEn":"Institutions where Indigenous children were forcibly confined and forbidden to speak family languages.","defZh":"原住民儿童被强制收容并被禁止使用家庭语言的机构，造成深重的语言与文化伤害。"},{"en":"oralism","zh":"口语主义","defEn":"The view that vocal language is more important than signed language.","defZh":"认为有声语言比手语更重要的观念，常使聋童失去手语输入。"},{"en":"aphasia","zh":"失语症","defEn":"A language impairment, often resulting from a stroke, that affects communication.","defZh":"一种常由中风引起的语言障碍，会影响患者的沟通方式与沟通能力。"},{"en":"language documentation","zh":"语言记录","defEn":"Recording a language's words and structures, which can support reawakening sleeping languages.","defZh":"对语言的词汇与结构进行记录，可为唤醒沉睡语言提供材料。"}],"examples":[{"text":"Jesuits generally derided the languages, characterizing the polysynthetic character of American languages as a symptom of social decay.","noteEn":"Gray shows missionaries treated complex grammars as evidence of social decay.","noteZh":"格雷指出，传教士把复杂的语法特征视为社会衰败的证据。"},{"text":"the habits and modes of thought of white men","noteEn":"The stated assimilation goal of the Canadian colonial government, quoted in the TRC report.","noteZh":"加拿大殖民政府公开宣称的同化目标，语出真相与和解委员会报告所引材料。"},{"text":"when linguists used standard interview techniques to research autistic people’s conversation, they found “deficits” in their pragmatic abilities","noteEn":"Salt found such deficits disappeared when autistic participants talked to each other.","noteZh":"索尔特发现，自闭症参与者彼此交谈时，这些所谓缺陷便不复存在。"}],"body":[{"en":"Science is not inherently virtuous: humans can use its tools, including linguistics, to do harm. Much foundational work was carried out by Christian missionaries whose goal was less to discover mental grammar than to convert people. Missionaries in what is now called Canada documented Indigenous languages so they could teach Christian doctrine and conduct trade, using the Roman alphabet and assumptions drawn from Latin and other European languages. Because that alphabet was developed for European languages, it represents other languages' phonetics inaccurately, and writing texts froze that form of the language, so some variation fell out of use.","zh":"科学并非天然高尚：人类可以用它的工具，包括语言学，造成伤害。语言学许多奠基性工作由基督教传教士完成，他们的目标与其说是揭示心理语法，不如说是让人皈依。来到今天称为加拿大的这片土地上的传教士，记录原住民语言以便传授基督教教义、进行贸易；他们使用罗马字母，并依据从拉丁语和其他欧洲语言得来的假设。由于这套字母本是为欧洲语言发展起来的，用它转写其他语言的语音并不准确；写下文本还「冻结」了该语言形式，使部分变异退出使用。"},{"en":"These effects were neither accidental nor benign: from the missionaries' own writings we can see that they considered Indigenous languages inferior, complaining incorrectly that the languages had no words for soul, belief and angel. The documentation was inaccurate and led to the loss of many features, although it has in some cases served as source material for reawakening sleeping languages like Huron-Wendat. Eliminating Indigenous languages and cultures was the stated goal of the Canadian government, and officials forcibly seized Indigenous children and sent them to residential schools, where they were separated from their families, forbidden their languages, starved and abused. Under such conditions, using English or French was a matter of sheer survival.","zh":"这些后果既非偶然，也并非无害：从传教士自己的文字可以看出，他们认为原住民语言低劣，错误地抱怨这些语言没有表示灵魂、信仰和天使的词。这些记录并不准确，导致许多语言特征流失，尽管其中一些文献后来成为唤醒休伦-温达特语等沉睡语言的素材。消灭原住民语言与文化是加拿大政府公开宣称的目标；官员强行夺走原住民儿童送进寄宿学校，使他们与家庭分离、被禁止说本族语言、挨饿并遭受虐待。在这样的条件下，说英语或法语是纯粹的生存问题。"},{"en":"Modern linguistics has also harmed minoritized languages and disabled people. Linguists rely on language users for data, but those who answer our questions do not always get much in return: data may end up only in obscure publications instead of being made available to the community, and a descriptive linguist risks appropriation by becoming an authority on a language without belonging to the community. Descriptions can also harden into prescriptive norms. Deaf children are often deprived of input because of oralism, and Salt showed that apparent pragmatic deficits in autistic people vanished when participants talked with each other. The lesson is humility: science is one way of knowing.","zh":"现代语言学也伤害了被边缘化的语言和残障者。语言学家依赖语言使用者提供语料，但回答我们问题的人并不总能得到回报：数据可能最终只存在于冷僻的出版物中，而没有提供给语言社群；一位描写取向的语言学家若在不属于该社群的情况下成为语言的权威，也面临挪用的风险。描写还可能固化为规定性规范。聋童常因口语主义而失去语言输入；索尔特表明，自闭症者身上看似存在的语用缺陷，在参与者彼此交谈时便不复存在。教训是保持谦逊：科学只是认识世界的一种方式。"}]},"chapter-006-slug-1-6-doing-good-with-language-science":{"title":{"en":"1.6 Doing good with language science","zh":"1.6 用语言科学做有益的事"},"summary":{"en":"Besides acknowledging the harms that linguistics has caused, the book asks how the tools of language science can be used to do good. Linguistics training prepares people for work in technology, in language-learning apps, in Indigenous language revitalization, in language teaching and in speech-language pathology. Linguists are also paid to interpret contracts, study how customers understand products, identify authors, name medications and create languages for film and television.","zh":"除了承认语言学曾造成的伤害，本节更关心如何用语言科学的工具去做一些有益的事。语言学的训练可以为技术行业、语言学习应用、原住民语言复兴、语言教学和言语病理学等领域做准备。语言学家还被雇来解读合同与政策、研究顾客如何理解产品、鉴定作者身份、为新药命名，并为影视作品创造全新的语言。语言无处不在，理解语言也是理解人的一部分。"},"points":[{"en":"Linguistics skills improve software for summarizing texts, translating, synthesizing speech and recognizing speech.","zh":"语言学的技能可用于改进文本摘要、翻译、语音合成与语音识别等软件。"},{"en":"Speech recognition handles standardized American English and lower voices better than higher voices and other accents.","zh":"语音识别对标准美式英语和较低嗓音的准确率较高，对较高嗓音和其他口音则差得多。"},{"en":"Linguists design language-learning apps, and metalinguistic awareness from linguistics can enhance language learning.","zh":"语言学家参与设计语言学习应用，而语言学带来的元语言意识也能促进语言学习。"},{"en":"Linguistic analysis supports Indigenous communities reclaiming or revitalizing their languages, following community leadership.","zh":"语言分析可支持原住民社群收回或振兴本族语言，但应以社群成员的引导为准。"},{"en":"Linguistics is a good entry point to ESL teaching certification and to clinical careers in speech-language pathology.","zh":"语言学是取得 ESL 教学资格的良好起点，也是进入言语病理学临床职业的途径。"},{"en":"Linguists are paid to interpret contracts, identify authors, name medications and invent languages for film and TV.","zh":"语言学家可受雇解读合同、鉴定作者身份、为新药命名，并为影视作品创造语言。"}],"terms":[{"en":"metalinguistic awareness","zh":"元语言意识","defEn":"Awareness of language itself as a system, which can support learning another language.","defZh":"把语言本身当作系统来审视的意识，有助于学习和教授另一种语言。"},{"en":"speech synthesis","zh":"语音合成","defEn":"Technology that produces natural-sounding spoken output for voice assistants and GPS devices.","defZh":"为语音助手、导航等设备生成听上去自然的语音输出的技术。"},{"en":"speech recognition","zh":"语音识别","defEn":"Technology that converts a person's speech into text or commands for a system.","defZh":"把人的话语转换为文本或系统指令的技术，其准确率会因口音和嗓音而异。"},{"en":"speech-language pathology","zh":"言语病理学","defEn":"A clinical field that assesses and treats impairments in producing or understanding language.","defZh":"评估并治疗语言产出或理解障碍的临床领域，如脑损伤后的言语治疗。"},{"en":"Indigenous language","zh":"原住民语言","defEn":"A language of an Indigenous people, often the target of reclaiming or revitalization efforts.","defZh":"原住民群体所使用的语言，常成为收回、复兴或振兴努力的对象。"}],"examples":[{"text":"That owl that scolds you if you skip your daily Esperanto practice was designed by linguists!","noteEn":"Example of linguists designing the language-learning apps that many learners use.","noteZh":"语言学家参与设计语言学习应用的例子，许多人正是通过这类应用学习语言。"},{"text":"speech therapy can sometimes recover some of that function","noteEn":"Illustration of how evidence from language science informs clinical treatment after brain injury.","noteZh":"说明语言科学的证据如何为脑损伤后的临床治疗提供依据。"},{"text":"identifying the author of a disputed document","noteEn":"One of the paid consulting activities that linguists the author knows have undertaken.","noteZh":"作者所认识的语言学家受雇承担的咨询工作之一，属于司法语言学的应用。"},{"text":"creating entirely new languages for film and TV series","noteEn":"Another industry use of linguistics training listed at the end of the section.","noteZh":"本节末尾列出的另一项产业应用：为电影和电视剧创造全新的语言。"}],"body":[{"en":"Linguistics, like many fields of academic inquiry, has done harm, and the previous section acknowledged that. Acknowledging those harms is only part of our responsibility. This book focuses on how the tools of language science can address some of them and do good in the world, and on what a background in linguistics can prepare you to do.","zh":"语言学像许多学术领域一样曾经造成伤害，上一节对此已作承认。但承认伤害只是责任的一部分。本书关注的是如何运用语言科学的工具去回应其中一些问题并在世界上做一些有益的事，同时也思考语言学的训练能让你从事什么。"},{"en":"In the tech sector, linguists improve software that summarizes texts, translates between languages, synthesizes natural-sounding speech for voice assistants and GPS, and helps those assistants understand speech. As the author notes, speech recognition does an okay job on standardized American English accents, especially lower voices, but is much less accurate for higher voices and for the many accents speakers actually use. Linguists also design language-learning apps, and the metalinguistic awareness gained from studying linguistics can enhance language learning.","zh":"在技术行业，语言学家改进文本摘要、跨语言翻译、为语音助手和导航合成自然语音，以及让语音助手听懂人话的软件。正如作者所说，语音识别对标准美式英语口音的处理尚可，对较低沉的嗓音尤其如此，但对较高的嗓音以及说话人实际使用的众多口音则准确度差得多。语言学家还参与设计语言学习应用，而学习语言学所获得的元语言意识也能促进语言学习。"},{"en":"Linguistics also supports Indigenous people who want to reclaim, revive or revitalize their languages, because analysis of these grammars helps create teaching materials and support adult learners who did not learn the language as children. Speaking as a settler, the author stresses following the lead of Indigenous community members rather than positioning oneself as the expert who saves the language. Linguistics training is likewise useful for language teaching and is a common entry point into ESL certification or into a clinical career in speech-language pathology, where language science informs treatment after brain injury or during a voice transition.","zh":"语言学还支持希望收回、复兴或振兴本族语言的原住民群体：对这些语法的分析有助于编写教学材料，帮助幼年没有机会学习本族语言的成年学习者。作者以定居者的身份强调，应追随原住民社群成员的引导，而不是把自己摆成拯救语言的专家。语言学的训练同样有益于语言教学，通常是取得 ESL 教师资格的切入点，也是进入言语病理学临床职业的常见途径；在那里，语言科学的证据指导着脑损伤后或声音转变过程中的治疗。"},{"en":"Linguists are called on in many other industries as well: testifying in court about the interpretation of contracts and policies, interpreting how customers understand the products they use, identifying the author of a disputed document, consulting on potential brand names for new medications, and creating entirely new languages for film and television. Language is everywhere and fundamental to how humans interact, so understanding how language works is part of understanding people.","zh":"语言学家的技能还被许多其他行业需要：在法庭上就合同与政策的解释作证、解读顾客如何理解他们使用的产品、鉴定争议文件的作者、为新药的品牌名称提供咨询，以及为电影和电视剧创造全新的语言。语言无处不在，是人类互动的基础，因此理解语言如何运作，也是理解人的一部分。"}]},"chapter-007-slug-1-7-do-chatbots-have-language":{"title":{"en":"1.7 Do ChatBots have Language?","zh":"1.7 聊天机器人有语言吗？"},"summary":{"en":"Human language is generative because speakers share a mental grammar and can always produce and understand new words and sentences. Large language models are only combinatorial: they calculate which pieces of language are likely to be related, based on a huge corpus of existing text, often scraped from copyrighted sources without consent. An LLM has no mind and no mental representation, so it cannot intend to communicate; any meaning in its output is meaning that human readers attribute to it.","zh":"人类语言具有生成性，因为说话人共享一套心理语法，能够不断产出并理解新的词句。大语言模型则只是组合性的：它依据一个庞大的既有文本语料库，计算哪些语言片段可能彼此相关，而这些语料常常未经作者同意就从受版权保护的材料中抓取。大语言模型没有心智，也就没有心理表征，无法有意图地传达信息；其输出中的意义只是人类读者赋予它的意义。"},"points":[{"en":"Human language is generative: speakers use a shared mental grammar to produce and understand endless new words and sentences.","zh":"人类语言具有生成性：说话人凭共享的心理语法不断产出并理解无穷的新词新句。"},{"en":"The label artificial intelligence is vague and covers systems that decide, classify, recommend, translate and generate text or images.","zh":"「人工智能」这个标签很含糊，涵盖做决定、分类、推荐、翻译以及生成文本或图像的系统。"},{"en":"A Large Language Model calculates the probability that given pieces of language are related, having been trained on a huge corpus.","zh":"大语言模型计算给定语言片段之间相关的概率，其训练依赖一个庞大的语料库。"},{"en":"The most popular commercial LLMs scrape millions of copyrighted sources whose authors have not consented to that use.","zh":"最流行的商业大语言模型从数百万受版权保护的来源抓取文本，作者从未同意这种使用方式。"},{"en":"A prompt about foraged mushrooms yields recipes only because cooking words co-occur with mushroom in the training data.","zh":"关于采摘蘑菇的提示会生成食谱，只是因为训练数据中烹饪类词语与 mushroom 经常共同出现。"},{"en":"Humans cannot help interpreting output, as with pareidolia, but an LLM has no intention and no shared understanding.","zh":"人总会不由自主地解读输出，就像空想性错视；而大语言模型没有意图，也没有共同的理解。"}],"terms":[{"en":"generativity","zh":"生成性","defEn":"The property of human language that lets users always do new things with it.","defZh":"人类语言的属性，使使用者总能用它做新的事，不断产出并理解从未见过的话语。"},{"en":"Large Language Model (LLM)","zh":"大语言模型","defEn":"A program that calculates the probability that given pieces of language are related to each other.","defZh":"一种通过海量文本训练、计算给定语言片段之间相关概率的程序。"},{"en":"corpus","zh":"语料库","defEn":"A large body of texts used as the data for training or analysis.","defZh":"为训练或分析而汇集的大量文本，大语言模型据此计算词语共现的概率。"},{"en":"mental representation","zh":"心理表征","defEn":"The conceptual knowledge of meaning that a language user holds in mind.","defZh":"语言使用者头脑中持有的关于意义的概念性知识，兼含事实知识与身体经验。"},{"en":"pareidolia","zh":"空想性错视","defEn":"The tendency to interpret anything even vaguely face-shaped as a face.","defZh":"把任何略像人脸的形状都看成一张脸的倾向，用以说明人会不由自主地赋予意义。"},{"en":"prompt","zh":"提示词","defEn":"Text that a user types into a chatbot in order to obtain a response.","defZh":"用户输入聊天机器人以获取回复的文本，如请它推荐一个用采摘蘑菇做的食谱。"}],"examples":[{"text":"suggest a recipe that uses foraged mushrooms","noteEn":"The prompt used to show that an LLM predicts rather than knows anything.","noteZh":"用于说明大语言模型只是在预测、而非真正「知道」什么的提示词。"},{"text":"users who listened to these songs also like these other artists","noteEn":"An example of an AI recommendation system listed early in the section.","noteZh":"本节开头所列人工智能推荐系统的例子，依据用户行为向用户推荐其他歌手。"},{"text":"it's not surprising that LLMs have a problem with the truth. Their goal is to provide a normal-seeming response to a prompt, not to convey information that is helpful to their interlocutor","noteEn":"The conclusion Hicks and his colleagues reach about LLMs and truth.","noteZh":"Hicks 及其同事关于大语言模型与真相的结论：其目标是回复看似正常，而非传达有用信息。"},{"text":"ChatGPT is bullshit","noteEn":"The blunt title of the Hicks et al. paper cited in this section.","noteZh":"本节所引 Hicks 等人论文的标题，措辞直白，概括了他们对该模型的判断。"}],"body":[{"en":"Previous sections showed that generativity is a key attribute of human grammar: you have an idea, generate a signal with your voice or hands, and your friend interprets it because you share a mental grammar. Lately, though, generative appears in the phrase generative AI, and it can feel as though ChatGPT, Claude and Gemini are generating human language. Bender and Hanna point out that artificial intelligence is a vague label covering computerized tasks that once relied on human judgment: deciding, classifying, recommending, translating and generating text.","zh":"前几节说明，生成性是人类语法的关键属性：你有一个想法，用声音或双手生成信号，朋友因为与你共享心理语法而能解读它。近来 generative 又出现在「生成式人工智能」中，让人感觉 ChatGPT、Claude 和 Gemini 真的在生成人类语言。Bender 和 Hanna 指出，「人工智能」是个含糊的标签，涵盖许多过去依赖人类判断的计算机任务：做决定、分类、推荐、翻译以及生成文本。"},{"en":"Text generation relies on Large Language Models, which calculate the probability that given pieces of language are related to each other, having been trained on a huge corpus of existing text. Some LLMs use open-source training data, but the most popular commercial ones scrape text from millions of copyrighted sources whose authors have not consented to that use.","zh":"文本生成依赖大语言模型，即在海量既有文本语料库上训练、计算给定语言片段之间相关概率的程序。有些模型使用开源训练数据，但最流行的商业模型却从数百万受版权保护的来源抓取文本，作者从未同意这种使用方式。"},{"en":"When you use language, you hold a conceptual representation of your message, including factual and embodied knowledge. An LLM has no mind, so it has no mental representation; prompted to suggest a recipe that uses foraged mushrooms, it predicts from its training data, where eggs, cheese and onions have a higher-probability relationship to mushroom than icing or sprinkles. That is not because the model knows mushroom cupcakes would be disgusting. Reading the response, you cannot help interpreting it, much as pareidolia makes us see a face in anything vaguely face-shaped.","zh":"你使用语言时，头脑中持有关于所传达意义的概念表征，兼含事实知识与身体经验。大语言模型没有心智，也就没有心理表征；当你提示它推荐一个用采摘蘑菇做的食谱，它只是根据训练数据预测——在数据中，eggs、cheese、onions 与 mushroom 的概率关系高于 icing、sprinkles。这并不是因为模型「知道」蘑菇纸杯蛋糕会很难吃。读到输出时，你仍会不由自主地解读它，就像空想性错视让我们在模糊形状中看到人脸。"},{"en":"That is quite different from talking with your housemate about dinner, where you share a goal and an understanding. Hicks and his colleagues put it bluntly: an LLM aims to give a normal-seeming response, not to convey information helpful to its interlocutor. Human language is generative, systematic and shared; LLMs are merely combinatorial, combining words into likely sequences. So when you meet generative AI, ask what generative and intelligence mean, and remember that artificial is the most accurate part of the term.","zh":"这与和室友讨论晚饭吃什么截然不同：你们有共同的目标和共同的理解。Hicks 及其同事说得很直白：大语言模型追求对提示给出看似正常的回复，而不是向对话者传达有用信息。人类语言具有生成性、系统性，并在人与人之间共享；大语言模型只是组合性的，把词拼成可能出现的序列。所以遇到「生成式人工智能」时，不妨追问 generative 与 intelligence 究竟指什么，并记住 artificial 才是这个说法中最准确的部分。"}]},"chapter-008-slug-1-8-how-do-chatbots-synthesize-sentences":{"title":{"en":"1.8 How do ChatBots Synthesize Sentences?","zh":"1.8 聊天机器人如何合成句子？"},"summary":{"en":"This section explains how large language models synthesize realistic-looking sentences. The logic goes back to Shannon's work, inspired by Markov, and to the notion of an n-gram: a sequence of items occurring in a given order in a corpus. Bigram and trigram probabilities show how likely one token is given the preceding ones. Real LLMs, however, use neural networks, and their outputs are further shaped by reinforcement learning from human feedback.","zh":"本节说明大语言模型如何合成看似真实的句子。其逻辑可追溯到 Shannon 受 Markov 启发的工作，以及 n 元组的概念：在一个语料库中按特定顺序出现的条目序列。二元组与三元组的概率说明在给定前面若干词元时，下一个词元出现的可能性。不过真正的大语言模型使用神经网络，其输出还受到「基于人类反馈的强化学习」的调整。"},"points":[{"en":"An n-gram is a sequence of items occurring in a given order in a given corpus; a bigram has two items.","zh":"n 元组是在特定语料库中按特定顺序出现的条目序列，二元组包含两个条目。"},{"en":"In English text Q is followed by U about 99% of the time, while E can be followed by any letter.","zh":"在英语文本中，Q 之后约 99% 的情况是 U，而 E 之后可以接任何字母。"},{"en":"Inside an LLM the items are tokens, usually words, morphemes or punctuation marks rather than single letters.","zh":"在大语言模型内部，这些条目是词元，通常是词、语素或标点，而不是单个字母。"},{"en":"After the trigram proud of, the next token is likely to be you, but a proper name lowers that probability.","zh":"在三元组 proud of 之后，下一个词元很可能是 you，但换成专有名词会降低该序列的概率。"},{"en":"LLMs do not actually use n-grams; they use neural networks whose weighted perceptrons link inputs to outputs.","zh":"大语言模型实际并不使用 n 元组，而是使用由带权重的感知机连接输入与输出的神经网络。"},{"en":"Reinforcement learning from human feedback lets underpaid workers shape outputs, at a serious cost to their mental health.","zh":"基于人类反馈的强化学习让低薪工人参与塑造输出，却以他们的心理健康为沉重代价。"}],"terms":[{"en":"n-gram","zh":"n 元组","defEn":"A sequence of items that occur in a given order in a given corpus.","defZh":"在特定语料库中按特定顺序出现的条目序列，其概率由该序列出现的频率算出。"},{"en":"bigram","zh":"二元组","defEn":"Two items, such as two letters or two words, that occur together in a corpus.","defZh":"在语料库中共同出现的两个条目，例如相邻的两个字母或两个词。"},{"en":"token","zh":"词元","defEn":"A unit that an LLM treats as an item, such as a word, morpheme or punctuation mark.","defZh":"大语言模型处理的基本单位，可能是词、语素或标点符号，而不一定是字母。"},{"en":"perceptron","zh":"感知机","defEn":"A mathematical function that takes multiple inputs and calculates a value to output.","defZh":"接受多个输入并据此计算输出数值的数学函数，是神经网络的组成单元。"},{"en":"neural network","zh":"神经网络","defEn":"A connected network of perceptrons whose weighted links carry influence from one to the next.","defZh":"由感知机相互连接而成的网络，各连接的权重表示一个单元对下一个单元的影响强度。"},{"en":"reinforcement learning from human feedback","zh":"基于人类反馈的强化学习","defEn":"Training in which human workers rate outputs and their ratings are fed back into the model.","defZh":"由人工评分员对模型输出评分并加标签，再把评分反馈回模型以调整其行为的训练方式。"}],"examples":[{"text":"This cake is ___","noteEn":"A context for which the model gives high probability to delicious, moist or chocolatey.","noteZh":"在此语境中，delicious、moist 等词概率高，crunchy 等词概率低。"},{"text":"Do you want me to give you a full step-by-step baked mac & cheese recipe?","noteEn":"A sentence Copilot synthesized after the author's prompt about baking mac and cheese.","noteZh":"作者询问烤通心粉奶酪后，Copilot 合成的一句话，用 I 和 you 使输出像对话。"},{"text":"how long do I bake nana’s mac & cheese for","noteEn":"The example of texting your mom, compared with prompting a chatbot the same question.","noteZh":"给妈妈发短信的示例，用来说明与向聊天机器人提出同一个问题时的相似感受。"},{"text":"You have to spend your whole day looking at dead bodies and crime scenes. Mental health support was not provided","noteEn":"A data labeller describing the trauma behind reinforcement learning work.","noteZh":"一位数据标注员描述强化学习背后劳动的创伤，出自 Kanyugi 被引用的陈述。"}],"body":[{"en":"This section digs into the word-combining process: how do LLMs synthesize realistic sentences? It considers only written text. The logic goes back to Shannon's work, inspired by Markov, and to the n-gram: a sequence of items occurring in a given order in a corpus. In a corpus of English text, Q is followed by U about 99% of the time and by any other letter less than 1%, making QU a high-probability bigram. E is far more frequent and can be followed by any letter at all. Bigram probabilities tell us how likely Thing 2 is, given that Thing 1 has just happened.","zh":"本节深入探讨这种组词过程：大语言模型究竟如何合成看似真实的句子？这里只讨论书面文本。其逻辑可追溯到受 Markov 启发的 Shannon 的工作，以及 n 元组的概念：在一个语料库中按特定顺序出现的条目序列。在英语文本语料库中，Q 之后约 99% 的情况是 U，其他字母不到 1%，因此 QU 是一个高概率二元组。E 常见得多，后面可以接任何字母。二元组概率告诉我们的是：在条目一刚刚出现的情况下，条目二有多可能。"},{"en":"Inside an LLM, those things are tokens, and a token is more likely to be a word, a morpheme or a punctuation mark than a letter. With word tokens we calculate trigrams, the probability of Token 3 given that Tokens 1 and 2 have just occurred; after proud of, the next token is pretty likely to be you. An n-gram extends the same logic to N items, but exact probabilities over billions of texts become unwieldy, so LLMs use neural networks: composites of perceptrons whose weighted connections set the strength of influence between units. Those weights make delicious, moist or chocolatey likely after This cake is.","zh":"在大语言模型内部，这些条目称为词元，它更可能是词、语素或标点符号，而不是字母。以词为词元时，可以计算三元组，即在词元一和词元二出现后词元三的概率；proud of 之后很可能是 you。n 元组把同样的逻辑扩展到 N 个条目，但在数十亿文本上计算精确概率很快会变得难以处理，所以大语言模型改用神经网络：由感知机构成的复合体，各连接的权重决定单元之间影响的强弱。这些权重让模型判断 This cake is 后面很可能是 delicious、moist 或 chocolatey。"},{"en":"Once trained, a model synthesizes text token by token, choosing from many high-probability words rather than always the single likeliest one, so its outputs vary. Creators also add safety filters or guardrails and refine the model with reinforcement learning from human feedback: workers rate and tag outputs, and their ratings feed back into the model. Those workers are often severely underpaid and must view horrific content; one data labeller reported spending whole days looking at dead bodies and crime scenes without mental health support. Released chatbots use I and you to feel like conversation, but a conversation involves shared intentions and understanding, which a chatbot lacks.","zh":"模型训练完成后逐个词元地合成文本，并且不总选概率最高的那个，而是在许多高概率词中挑选，因此输出会有变化。创作者还会加入安全过滤器或护栏，并用「基于人类反馈的强化学习」改进模型：工人为输出评分并加标签，评分再反馈回模型。这些工人往往报酬极低，还必须观看可怕的内容；一位数据标注员说，自己整天都在看尸体和犯罪现场，却得不到心理健康支持。模型发布后会用 I 和 you 让输出像对话，但真正的对话包含共同意图与相互理解，而聊天机器人并不具备这些。"}]},"chapter-009-exercises":{"title":{"en":"1.9 Exercise your linguistics skills","zh":"1.9 练一练语言学技能"},"summary":{"en":"This section offers four exercises that apply the chapter's ideas to the reader's own language experience. They ask for descriptive observations about a first language, for the invention and evaluation of new product names, for new verbs coined from nouns, and for a dictionary definition of a word that has only recently entered English.","zh":"本节提供四个练习，把本章的理念用于读者自身的语言经验：先界定第一语言与 L1，并对自己的第一语言作出描写性而非规定性的科学观察；再为初创公司的新产品发明独一无二的名称，并评判其他学生所造名称的优劣；接着由名词创造新动词，以体会心理语法的生成性；最后为刚进入英语不久、尚未收入主流词典的新词，根据语境中的用法编写词典释义。"},"points":[{"en":"First language and L1, sometimes called native language, means the language learned in very early childhood from surrounding people.","zh":"第一语言（first language）与 L1（有时称母语 native language）指在幼年早期从周围人那里习得的语言。"},{"en":"Many people have more than one L1, and observations about a language must be descriptive rather than prescriptive.","zh":"许多人不只拥有一门第一语言；对语言的观察必须是描写性的，而不是规定性的。"},{"en":"A good product name must be unique, and readers are asked to judge which invented names work and why.","zh":"好的产品名称必须独一无二；读者需要判断哪些生造名称可行，以及原因何在。"},{"en":"Mental grammar is generative: new words, including new verbs made from nouns or proper names, can always be created.","zh":"心理语法具有生成性：新词总能被创造出来，包括由名词或专有名词转成的新动词。"},{"en":"Words that are too new for mainstream dictionaries can still be defined from observed uses in context.","zh":"尚未收入主流词典的新词，仍可根据在语境中观察到的用法加以定义。"}],"terms":[{"en":"first language / L1","zh":"第一语言 / L1","defEn":"The language a person learned from surrounding people in very early childhood.","defZh":"一个人幼年早期从周围人那里习得的语言，许多人可以拥有不止一门第一语言。"},{"en":"native language","zh":"母语","defEn":"Another name for a first language, sometimes used when only one is assumed.","defZh":"第一语言的另一种说法，通常在假定一个人只有一门母语时使用。"},{"en":"descriptive","zh":"描写性的","defEn":"Describing how a language is actually used rather than how it ought to be used.","defZh":"如实描述语言实际的使用方式，而不去规定它应当如何使用。"},{"en":"prescriptive","zh":"规定性的","defEn":"Stating how a language should be used, often judging some usages as incorrect.","defZh":"规定语言应当如何使用，往往把某些实际存在的用法判定为不正确。"},{"en":"generative","zh":"生成性的","defEn":"The property of mental grammar that allows speakers to create new words and sentences.","defZh":"心理语法的一种属性，使说话者能够创造出此前从未听过的新词与新句子。"},{"en":"mental grammar","zh":"心理语法","defEn":"The system of knowledge in a speaker's mind that underlies language use.","defZh":"存在于说话者心智之中、支撑其理解与生成语言的知识系统。"}],"examples":[{"text":"We’re Megabussing to Montreal this weekend.","noteEn":"A proper name is turned into a new verb describing travel by that company.","noteZh":"专有名词被用作新动词，表示乘该公司的车前往某地。"},{"text":"You can find out the answer by Googling.","noteEn":"A brand name becomes a verb meaning to search for information online.","noteZh":"品牌名称被用作动词，表示在网上搜索并查找信息。"},{"text":"The kids got Pfizered before going back to school.","noteEn":"A company name becomes a verb meaning to receive that company's vaccine.","noteZh":"公司名称被用作动词，表示接种该公司生产的疫苗。"},{"text":"mentocular, swoodiei, torrix, baizan, jibberdab, keerild, euquinu, tuitionary, kzen, zirka, hbiufk, fluxon","noteEn":"Invented product names from other students, to be judged for how well they work.","noteZh":"其他学生生造的产品名称，需要判断哪些名称更可行。"}],"body":[{"en":"The section consists of four exercises that turn the chapter's concepts back on the reader's own linguistic knowledge. The first asks for a definition in use: first language and L1, or native language, name the language a person learned from the people around them in very early childhood. Since many people have more than one L1, readers are asked how many they have and then told to make two scientific observations about one of them, remembering that such observations must be descriptive and not prescriptive.","zh":"本节由四个练习构成，把本章的概念反过来用在读者自身的语言知识上。第一个练习围绕术语的实际用法：第一语言与 L1（或称母语）指一个人在幼年早期从周围人那里习得的语言，而许多人并不止拥有一门第一语言。因此读者需先回答自己有几种第一语言，然后对其中一门作出两条科学观察，并牢记这类观察必须是描写性的，即如实记录语言的实际用法，而不是规定性的，即不评判某种说法是否正确。"},{"en":"The second exercise is an exercise in naming. Readers imagine working as the in-house linguist for a start-up and must invent a unique name for its new product, a name that does not already exist. They then examine a list of names produced by other students, such as mentocular, torrix, baizan and fluxon, and decide which of them are good product names and which are not, asking what makes a name good and how one can know.","zh":"第二个练习是关于命名的任务。读者设想自己是一家初创公司的内部语言学家，必须为该公司的新产品发明一个独一无二、此前并不存在的名称。随后要审视其他学生给出的名称清单，例如 mentocular、torrix、baizan、fluxon，判断其中哪些是好的产品名称、哪些不是，并追问好名称的标准是什么、又如何知道。"},{"en":"The third exercise demonstrates that mental grammar is generative, since it is always possible to create new words. English readily forms new verbs from existing nouns, even from proper names, as in We’re Megabussing to Montreal this weekend, You can find out the answer by Googling, and The kids got Pfizered before going back to school. Readers must coin three new verbs from common nouns or proper names and place each in a sentence that shows its meaning.","zh":"第三个练习说明心理语法具有生成性，因为新词总是可以被创造出来。英语很容易由已有的名词构成新动词，甚至可由专有名词构成，例如 We’re Megabussing to Montreal this weekend、You can find out the answer by Googling、The kids got Pfizered before going back to school。读者需要由普通名词或专有名词造出三个新动词，并各造一句以显示其意义。"},{"en":"The fourth exercise turns to lexical change as it happens. Readers choose a word that has only recently entered English, so recent that it is not yet in mainstream dictionaries, and then collect examples of it being used in context, either in ordinary conversation or by searching online. On the basis of those observed uses, they write a dictionary definition of the word, practising definition as a descriptive task rather than a prescriptive one.","zh":"第四个练习关注正在发生的词汇变化。读者选一个刚进入英语不久、尚未收入主流词典的新词，然后在日常对话中或通过网络检索，收集它在语境中的用例。根据观察到的用法，为该词撰写一条词典释义，从而把下定义当作描写性任务而非规定性任务来练习。"}]},"part-002-chapter-2-language-power-privilege":{"title":{"en":"Chapter 2: Language, Power, and Privilege","zh":"第 2 章：语言、权力与特权"},"summary":{"en":"Language is central to human interaction: we use it to communicate ideas and information, and also to express and construct our identities. This chapter therefore opens the book by examining the social aspects of language, focusing on how power and language relate to each other. It also asks learners to collect real-world examples and to reflect on their own and others' language attitudes.","zh":"语言是人类互动的核心：我们既用它交流思想与信息，也用它表达并建构身份认同。因此本章作为全书开篇，考察语言的社会面向，重点讨论权力与语言之间的关联。本章还要求学习者搜集现实中的实例，并反思自己与他人的语言态度。"},"points":[{"en":"Through language we communicate ideas and information and also express and construct aspects of our identity.","zh":"我们借助语言交流思想与信息，同时也表达并建构自身身份认同的各个面向。"},{"en":"This chapter investigates the social aspects of language, beginning with relationships between power and language.","zh":"本章考察语言的社会面向，并从权力与语言的关系入手展开讨论。"},{"en":"Learners should find real-world examples of power-language relationships and interpret language attitudes metalinguistically.","zh":"学习者应能找到权力与语言关系的真实案例，并以元语言意识解读自己和他人的语言态度。"}],"terms":[{"en":"power","zh":"权力","defEn":"The social force that shapes whose language is valued, legitimated, or dismissed.","defZh":"塑造哪些语言被重视、被认可或被贬低的社会力量，也决定说话者在社会中的地位。"},{"en":"identity","zh":"身份认同","defEn":"The socially constructed sense of who we are, expressed partly through language.","defZh":"对自身究竟是谁的社会性建构，部分通过日常语言使用加以表达和维持。"},{"en":"metalinguistic awareness","zh":"元语言意识","defEn":"The ability to reflect on and talk about language itself as an object.","defZh":"把语言本身当作一个对象来加以反思、评价和谈论的能力。"}],"examples":[],"body":[{"en":"Language is a central part of how human beings interact with one another. We do not only pass along ideas and information; we also express who we are and actively build aspects of our identity through the language we use. Because these social dimensions matter so much, the book begins here, with the social side of language.","zh":"语言是人类彼此互动的核心组成部分。我们不仅传递思想与信息，也借由所用的语言表达自身是谁，并主动建构身份认同的各个面向。正因这些社会维度极为重要，本书便由此起步，从语言的社会面向谈起。"},{"en":"The chapter examines how power and language are connected across a range of situations, from everyday conversation to the ways institutions talk about people. By the end, readers should be able to describe those relationships, notice real-world examples of them, and use their metalinguistic awareness to interpret the attitudes that they and other people hold about language. The aim is not to catalogue facts about particular languages but to notice how language works socially.","zh":"本章考察权力与语言在多种情境中的联系，从日常交谈到机构谈论人的方式。读完之后，读者应能描述这些关系，留意现实生活中的相关实例，并运用元语言意识来解读自己与他人对语言所持的态度。其目的不在于罗列个别语言的事实，而在于留意语言在社会中如何运作。"}]},"chapter-010-slug-2-1-language-and-identity":{"title":{"en":"2.1 Language and identity","zh":"2.1 语言与身份认同"},"summary":{"en":"Some utterances do not merely describe the world but change it: a wedding vow, a concession, or the words you're hired all bring about real consequences. Austin called these performative speech acts, and their force depends on authority, sincerity, context, and audience uptake. Butler extended performativity to identity, arguing that gender and other identities are accomplishments built through repeated social practice, including language.","zh":"有些话语不只是描述世界，而是改变世界：婚礼誓词、认输、以及「你被录用了」都会带来真实的后果。奥斯汀把这类话语称为施为性言语行为，其效力取决于说话者的权威、真诚、语境以及受众的接受。巴特勒把施为性扩展到身份认同，主张性别等身份是通过包括语言在内反复进行的社会实践而达成的成就。"},"points":[{"en":"Performative speech acts such as I do and I now pronounce you married change reality rather than describing it.","zh":"诸如「我愿意」和「我现在宣布你们结为夫妻」这类施为性言语行为改变现实，而非仅仅描述现实。"},{"en":"Their force requires the authority and sincerity of the utterer plus recognition and acceptance by the audience.","zh":"这类话语的效力需要说话者的权威与真诚，也需要受众的承认与接受。"},{"en":"Children play-acting a wedding, or simply shouting I declare bankruptcy, produces no such effect.","zh":"孩子在游戏中扮演婚礼，或只是大喊「我宣布破产」，都不会产生同样的效果。"},{"en":"Butler extended performativity to identity, treating gender as a performative accomplishment reinforced by repetition.","zh":"巴特勒把施为性扩展到身份认同，将性别视为通过反复实践而不断强化的施为性成就。"},{"en":"All identity is socially constructed through sustained practice, as when using eh marks Canadian identity.","zh":"一切身份认同都通过持续的社会实践被社会性建构，例如使用 eh 标示出加拿大身份。"}],"terms":[{"en":"performative speech act","zh":"施为性言语行为","defEn":"An utterance that does not just convey information but performs an action affecting reality.","defZh":"不仅传递信息，还同时实施某种能够影响现实之行动的话语。"},{"en":"performativity","zh":"施为性","defEn":"The property of language and social practice by which they bring about effects in the world.","defZh":"语言与社会实践能够在现实世界中产生实际效果的属性。"},{"en":"identity","zh":"身份认同","defEn":"A socially constructed sense of self, actively built and expressed through repeated practice.","defZh":"通过反复实践主动建构并表达出来的、社会性的自我认知。"},{"en":"uptake","zh":"接受（受众认可）","defEn":"The audience's recognition and acceptance of an utterance's intended performative force.","defZh":"受众对某一话语所意图实施的施为效力的承认与接受，是施为成功的关键。"}],"examples":[{"text":"I now pronounce you married","noteEn":"Spoken by a licensed officiant, these words actually make two people married.","noteZh":"由持证主婚人说出的这句话，真正使两人成为夫妻。"},{"text":"I declare bankruptcy!","noteEn":"Simply shouting this phrase does not erase the credit-card debt you owe.","noteZh":"仅仅喊出这句话并不能免除你的信用卡债务。"},{"text":"eh","noteEn":"Using this stereotype of Canadian English constructs and reinforces a Canadian identity.","noteZh":"使用这个加拿大英语的刻板特征，会建构并强化加拿大身份。"},{"text":"Is that a hint of Cascade hops on the finish?","noteEn":"Craft beer jargon that stakes a claim to membership in that community.","noteZh":"精酿啤酒的行话，借此宣称自己属于该社群。"}],"body":[{"en":"Language does more than carry information: certain utterances actually change the world. At a wedding, the partners' I do and the officiant's I now pronounce you married leave the couple married, with material consequences such as filing taxes together, sharing medical insurance, or gaining spousal privilege. The philosopher J. L. Austin, in How to Do Things With Words, called such utterances performative speech acts: they convey information and at the same time perform an action that affects reality. Conceding a chess game with I concede or hearing you're hired after an interview works the same way.","zh":"语言不只是传递信息：某些话语确实会改变世界。在婚礼上，新人说出的「我愿意」和主婚人说出的「我现在宣布你们结为夫妻」，使两人真正成为夫妻，并带来共同报税、共享医疗保险或获得配偶特权等实际后果。哲学家奥斯汀在《如何以言行事》中把这类话语称为施为性言语行为：它们既传递信息，又同时实施某种影响现实的行动。下棋时说「我认输」而结束比赛，面试后听到「你被录用了」，作用方式也是如此。"},{"en":"Performativity, however, depends on context and on social recognition. Children acting out a wedding cannot marry anyone no matter how loudly they pronounce the words, and shouting I declare bankruptcy does not erase credit-card debt. The power of words to act rests on the authority and sincerity of the utterer together with the uptake of the audience and the wider population. Society has to agree that particular words can do particular things in particular contexts; where such agreement is lacking, serious conflict can follow.","zh":"然而，施为性依赖语境和社会承认。孩子们在游戏中扮演婚礼，无论把誓词喊得多响，也不能真的让谁结婚；高喊「我宣布破产」同样无法消除信用卡债务。话语的行动力取决于说话者的权威与真诚，也取决于受众乃至更广泛人群的接受。社会必须一致同意某些话语在特定语境中能够完成某些事情；一旦缺乏这种共识，就可能引发严重的冲突。"},{"en":"Judith Butler extended performativity beyond individual speech acts, arguing that social practices generally, language included, help create and express identity. On her account gender is a performative accomplishment: practices associated with men or women are perceived as masculine or feminine, and repeated expression of them reinforces the link. Extending this idea, every aspect of identity is socially constructed through sustained practice. Swearing in a lecture signals casualness, and craft beer jargon such as asking about a hint of Cascade hops claims membership in that community. Performativity is not stage acting; it is the way we make ourselves through our behaviour.","zh":"朱迪斯·巴特勒把施为性从个别言语行为扩展到更广的范围，主张包括语言在内的一般社会实践也有助于创造和表达身份认同。在她看来，性别是一种施为性成就：与男性或女性相关联的实践被感知为男性化或女性化，而反复的表达会强化这种联系。把这一思路推广开来，身份认同的每个面向都是通过持续实践被社会性建构的。在课堂上说脏话表示随意，而用「收尾时是不是有一丝卡斯卡特啤酒花的味道？」这样的精酿行话，则是在宣称自己属于该社群。施为性并非舞台表演，而是我们借由行为塑造自身的方式。"}]},"chapter-011-slug-2-2-language-and-offense":{"title":{"en":"2.2 Language and offence","zh":"2.2 语言与冒犯"},"summary":{"en":"Language also carries emotional force, and some expressions are taboo: their use is avoided in most circumstances because violating the taboo causes offence. Taboos may rest on negative feelings, as with swear words, or on respect, as when Kambaata women avoid sounds matching their in-laws' names. The section also distinguishes using a word from mentioning it, a difference that matters greatly for swear words and slurs.","zh":"语言还带有情感力量，某些表达属于禁忌：由于违反禁忌会造成冒犯，人们在多数场合都避免使用它们。禁忌可能源于负面情感，如脏话；也可能出于尊重，如坎巴塔语女性回避与公婆名字相同的语音。本节还区分「使用」一个词与「提及」一个词，这一区别对脏话和种族蔑称尤为重要。"},"points":[{"en":"Poop and shit share a basic meaning, yet shit is taboo and its use in the wrong context causes offence.","zh":"poop 与 shit 基本意义相同，但 shit 属于禁忌，在不当语境中使用会造成冒犯。"},{"en":"Odour and aroma differ in association, with odour negative, but neither word is taboo.","zh":"odour 与 aroma 的联想不同，odour 偏负面，但二者都不构成禁忌。"},{"en":"In Kambaata a woman avoids sounds matching her in-laws' names, a taboo rooted in respect.","zh":"在坎巴塔语中，女性回避与公婆名字相同的语音，这种禁忌源于尊重。"},{"en":"Taboo avoidance replaces forbidden words with alternate forms, or with similar-sounding words like sugar or shoot.","zh":"禁忌回避以其他形式替换禁忌词，或用 sugar、shoot 这类音近词替代。"},{"en":"The use-mention distinction separates ordinary use of a word from talking about the word itself.","zh":"使用—提及区分把词语的日常使用与谈论该词本身区分开来。"},{"en":"Even mentioning highly volatile taboo words, such as racial slurs, can cause visceral offence.","zh":"即便只是提及种族蔑称这类高度敏感的禁忌词，也可能引发强烈的冒犯感。"}],"terms":[{"en":"taboo","zh":"禁忌","defEn":"A restriction on a word or expression whose use is avoided in most circumstances.","defZh":"对某词语或表达的限制，除特定场合外都要避免使用它，违反即造成冒犯。"},{"en":"taboo avoidance","zh":"禁忌回避","defEn":"The replacement of taboo words with other words or alternative forms.","defZh":"用其他词语、音近词或替代形式来替换禁忌词，以避免违反禁忌的做法。"},{"en":"use-mention distinction","zh":"使用—提及区分","defEn":"The difference between using a word to refer and mentioning it as a linguistic object.","defZh":"把词语用于指称与把词语作为语言对象加以提及之间的区别。"},{"en":"racial slur","zh":"种族蔑称","defEn":"A taboo word that insults and denigrates a marginalised group on the basis of perceived race.","defZh":"基于被感知的种族而侮辱、贬损某一边缘化群体的禁忌词。"},{"en":"metalinguistic","zh":"元语言的","defEn":"Describing language use that talks about language itself rather than about the world.","defZh":"指谈论语言本身、把词语当作语言对象而非谈论外部世界的语言使用方式。"}],"examples":[{"text":"Do you need to take a shit?","noteEn":"Said to a young child, this taboo use would offend many adults.","noteZh":"对幼童说出这句带禁忌词的话，会让许多成年人反感。"},{"text":"a married Kambaata woman whose father-in-law is named Tiráago might replace the word timá 'leftover dish' with ginjirá","noteEn":"An alternate form avoids the initial ti- sound matching the in-law's name.","noteZh":"使用替代形式以避开与公公名字相同的词首 ti- 音。"},{"text":"sugar or shoot when they stub their toe instead of shit","noteEn":"Similar-sounding replacements keep some of the emotional force while reducing the resulting offence.","noteZh":"音近的替代词保留了部分情感力量，同时减少了冒犯。"},{"text":"wheat is a grain","noteEn":"Here wheat is used to talk about the physical grain itself.","noteZh":"此处 wheat 是被使用来谈论谷物本身。"}],"body":[{"en":"Beyond communicating literal meaning, language has emotional power over those who produce and hear it. Swear words illustrate this clearly. Although poop and shit refer to the same substance, only shit is taboo, meaning its use is avoided in most circumstances and violating that taboo causes offence. Shouting Oh, poop! over a stubbed toe offends no one, while asking a child Do you need to take a shit? would offend many adults. By contrast, odour and aroma both name smells but carry different associations, and mixing them up offends nobody.","zh":"除了传达字面意义之外，语言还对说者和听者具有情感层面的力量。脏话清楚地说明了这一点。尽管 poop 与 shit 指同一事物，却只有 shit 属于禁忌，也就是说除特定场合外人们都避免使用它，违反这一禁忌就会冒犯他人。踢伤脚趾时喊一声 Oh, poop! 不会冒犯任何人，而问孩子 Do you need to take a shit? 却会让许多成年人反感。相比之下，odour 与 aroma 都指气味，只是联想不同：我们说不愉快的气味用 odour，说怡人的香气用 aroma，但把二者用混并不会冒犯谁。"},{"en":"Taboos are not always motivated by negativity. In Kambaata, a Highland East Cushitic language of Ethiopia, a woman avoids any word beginning with the same sounds as her spouse's parents' names, out of respect rather than dislike, relying on taboo avoidance. A woman whose father-in-law is named Tiráago might replace timá 'leftover dish' with ginjirá to avoid the matching ti- sound. Elsewhere the opposite strategy is used: swear words are replaced by similar-sounding items such as sugar or shoot, which retain some emotional force while minimizing offence. Taboos commonly cover in-laws and elders, bodily waste, sex, death, and religion.","zh":"禁忌的动因并不总是负面的。在埃塞俄比亚的坎巴塔语（亚非语系高地东库施特语）中，女性传统上要回避任何以配偶父母名字相同语音开头的词，这出于尊重而非厌恶，她依靠禁忌回避，用别的词替换禁忌词。若公公名为 Tiráago，她可能把 timá（‘剩菜’）换成 ginjirá，以避开相同的 ti- 音。另一些语言则采用相反的策略：用 sugar、shoot 这类音近词替换脏话，既保留部分情感力量，又把冒犯降到最低。常见的禁忌范围包括公婆与长者、身体排泄物、性器官与性行为、死亡以及宗教事物或观念。"},{"en":"Language can describe itself, which makes linguistics possible: speakers hold metalinguistic conversations in which words are mentioned as linguistic objects rather than used to refer to things. The convention for marking mentioned words is italics. This use-mention distinction matters most for taboo vocabulary. Mentioning a taboo word need not invoke the taboo the way using it does, so a textbook can discuss the word shit as a linguistic phenomenon. It is not, however, a free pass. Racial slurs, which insult and denigrate marginalised groups, cause visceral reactions even when merely mentioned, and some contexts are so sensitive that even mentions violate the taboo. Speakers then use circumlocutions like a four-letter word referring to excrement, masking with asterisks or dashes (s***, s–t), the initial letter (s-word), or bleeping audio.","zh":"语言还能描述自身，这正是语言学得以成立的前提：普通说话者也会进行元语言对话，此时词语是被提及的语言对象，而非用来指称事物。标记被提及词语的惯例是使用斜体。这一使用—提及区分对禁忌词汇尤为要紧。提及某个禁忌词，未必像使用它那样唤起禁忌，因此教材可以讨论 shit 这个词作为一种语言现象。但这并不等于通行无阻。种族蔑称侮辱并贬损边缘化群体，即便只是提及也会引发强烈反应；有些语境对禁忌极为敏感，连提及都构成违反。此时说话者会改用迂回说法，如「指排泄物的四字母词」，或用星号、破折号遮蔽（s***、s–t）、只称首字母（s-word）、对音轨做消音处理，或对图像视频打码。"}]},"chapter-012-slug-2-3-derogation-toxicity-and-power-imbalances":{"title":{"en":"2.3 Derogation, toxicity, and power imbalances","zh":"2.3 贬抑、毒性言语与权力失衡"},"summary":{"en":"Language can express solidarity, but it can also do harm. This section distinguishes offense, which concerns the impact on discourse participants, from derogation, which concerns the utterer's condemning attitude, and shows how particularistic insults differ from slurs in scope. Slurs draw their extraordinary force from power imbalance, which also explains why some can be reclaimed.","zh":"语言既能表达团结，也会造成伤害。本节区分冒犯与贬抑：前者关乎对会话参与者的影响，后者关乎说话人的谴责态度，并说明个别性侮辱与侮辱语在作用范围上的差别。侮辱语的巨大力量源自权力失衡，这也解释了为何某些侮辱语可以被重新夺回。"},"points":[{"en":"Language can build solidarity, as with Japanese name suffixes, but it can also cause offense to discourse participants.","zh":"语言既能建立团结，例如日语名字后缀所体现的亲近，也会对会话参与者造成冒犯。"},{"en":"Offense concerns the impact on participants, while derogation concerns the utterer's condemning attitude towards the referent.","zh":"冒犯关乎对参与者造成的影响，贬抑则关乎说话人对指称对象所持的谴责态度。"},{"en":"Particularistic insults target one person for a specific act, whereas slurs denigrate entire marginalized groups.","zh":"个别性侮辱针对某人某次具体行为，侮辱语则贬低整个边缘化群体。"},{"en":"The toxicity of slurs rests on power imbalance and invokes historical violence against the targeted group.","zh":"侮辱语的毒性以权力失衡为基础，并会唤起针对目标群体的历史暴力。"},{"en":"Slurs such as queer and suffragette have been reclaimed, becoming identity markers or mainstream terms.","zh":"queer 与 suffragette 等侮辱语已被重新夺回，如今成为身份标志或日常主流用语。"}],"terms":[{"en":"vulgarity","zh":"粗俗语","defEn":"An expression involving taboo bodily references, such as shit or ass.","defZh":"涉及禁忌性身体部位指称的词语或表达，例如 shit、ass 这类粗俗说法。"},{"en":"expletive","zh":"咒骂语（expletive）","defEn":"An expression used for an emotional outburst, such as damn.","defZh":"用于情绪爆发、愤怒或惊讶时脱口而出的词语，例如 damn 这类表达。"},{"en":"derogation","zh":"贬抑","defEn":"A kind of harm in which an expression disparages people and condemns the referent.","defZh":"一种语言伤害，指某些表达贬低他人、对指称对象表示谴责与否定。"},{"en":"slur","zh":"侮辱语","defEn":"An insult that denigrates a specific marginalized group rather than one individual.","defZh":"贬低某一特定边缘化群体、而非针对某个个人的侮辱性表达。"},{"en":"toxicity of slurs","zh":"侮辱语的毒性","defEn":"The especially offensive emotional power that slurs carry because of power imbalance.","defZh":"侮辱语因说话人与目标之间的权力失衡而具有的格外强烈的冒犯性情感力量。"}],"examples":[{"text":"kuso omoshire:","noteEn":"A Japanese vulgar expression glossed in the source as roughly 'fuckin' hilarious'.","noteZh":"日语粗俗表达，原文标注其大意相当于「他妈的太好笑了」。"},{"text":"I hate Mondays","noteEn":"A coded racial slur used to express bigotry without alerting those targeted.","noteZh":"用作暗语式种族侮辱，可在目标群体毫无察觉时表达偏执观点。"},{"text":"femoid","noteEn":"A slur against women that is used in certain online subcultures.","noteZh":"某些网络亚文化中经常使用的、针对女性的侮辱语。"},{"text":"suffragette","noteEn":"Coined in 1906 with the diminutive -ette as an insult, later adopted by activists.","noteZh":"1906 年用表小的 -ette 后缀造出以图侮辱，后被活动家自己采用。"}],"body":[{"en":"Earlier in this chapter we saw that language can perform actions and build identity, including positive social bonds such as the Japanese name suffixes -san and -chan. But language can also cause harm. Vulgarities such as shit cause offense, a social or psychological harm done to discourse participants. Offense does not depend on intent, and its severity varies with the expression and the context.","zh":"本章前文已经看到，语言可以实施行动、构建身份，也能建立积极的社会关系，例如日语名字后缀 -san 与 -chan 所体现的亲近程度。但语言同样会造成伤害。像 shit 这样的粗俗语会引发冒犯，而冒犯是对会话参与者造成的社会性或心理性伤害。冒犯并不取决于说话人的意图，其严重程度随表达本身与语境而变化。"},{"en":"Derogation, or pejoration, is a different kind of harm: derogatory expressions disparage people, as jerk and asshole condemn the referent. Offense concerns how participants are affected, while derogation concerns the utterer's attitude, so the two can come apart. An expletive such as shit may be offensive without being derogatory; a coded slur such as Monday is derogatory without causing offense to those who lack the in-group knowledge.","zh":"贬抑（derogation，又称 pejoration）是另一类伤害：贬抑性表达贬低他人，如 jerk 与 asshole 表达说话人对指称对象的谴责。冒犯关乎参与者受到的影响，贬抑关乎说话人的态度，二者可以分离。shit 这类咒骂语可能具有冒犯性却并不贬抑他人；而 Monday 这类暗语式侮辱语具有贬抑性，却不会让缺乏圈内知识的人感到冒犯。"},{"en":"Particularistic insults or general pejoratives, such as jerk, idiot, and asshole, condemn one person for one specific act. Slurs instead denigrate entire marginalized groups; femoid, for example, targets women. Their force comes from the power differential between user and target and invokes a history of violence against the group. Some research suggests slurs are processed in a different part of the brain (Singer, 1997); this is the toxicity of slurs. Insults aimed at high-status groups lack this power.","zh":"个别性侮辱（particularistic insults）或称一般性贬抑语，如 jerk、idiot、asshole，是针对某人某次具体行为表达强烈不满。侮辱语（slur）则贬低整个边缘化群体，例如 femoid 针对女性。侮辱语的力量来自使用者与目标之间的权力落差，并会唤起针对该群体的历史暴力；有研究显示侮辱语由大脑中与其他语言不同的部位处理（Singer, 1997），这就是所谓侮辱语的毒性（toxicity）。针对高地位群体的侮辱缺乏这种力量。"},{"en":"Because power imbalance is central, slurs can sometimes be reclaimed. Queer was long a slur against the 2SLGBTQ+ community before activists and academics reclaimed it in the 1990s, and suffragette, coined in 1906 with the diminutive -ette as an insult, was adopted by the activists themselves. Language both encodes and enforces social status, and metalinguistic awareness lets us examine and resist that damage.","zh":"正因权力失衡是核心，侮辱语有时也可能被重新夺回。queer 长期被用作针对 2SLGBTQ+ 群体的侮辱语，20 世纪 90 年代活动家与学者开始将其重新夺回，如今已成为常用统称；suffragette 由一位英国记者在 1906 年用表小的 -ette 后缀造出以图侮辱，却被活动家自己采用，如今不再被视为侮辱语。语言既编码又实施社会地位关系，元语言意识让我们得以审视并抵抗这种经由语言的伤害。"}]},"chapter-013-slug-2-4-the-power-of-names":{"title":{"en":"2.4 The power of names","zh":"2.4 名字的力量"},"summary":{"en":"Our names are tied to our personhood and reveal social categories. This section explains matched-guise studies, which hold a stimulus constant while varying the name attached to it, and reports Toronto findings that English-sounding names fare better with employers and landlords. It then considers reclaiming Indigenous names, deadnaming, and indexical bleaching.","zh":"名字与人格紧密相连，既标示个人，也标示其社会归属，并透露人所归属的社会范畴。本节介绍配对伪装研究：保持刺激材料不变，只改变所附的姓名，并报告多伦多的发现——名字听来像英语的人更受雇主与房东青睐。随后讨论原住民名字的重新使用、跨性别者遭遇的旧名指称与指称漂白。"},"points":[{"en":"Names point to individuals and also prompt guesses about a person's gender, age, and ethnicity.","zh":"名字既指向个人，也促使人据此推测其性别、年龄与族裔身份。"},{"en":"Matched-guise studies hold the stimulus constant and vary only the name, so rating differences must come from the name.","zh":"配对伪装研究保持刺激材料不变、只改变姓名，因此评分差异必定源自姓名。"},{"en":"Toronto studies found callbacks and landlord replies were less frequent for non-English-sounding names.","zh":"多伦多的研究发现，名字听来不像英语的申请者，获得回电与房东回复的比例更低。"},{"en":"Reclaiming Indigenous names resists colonial renaming, as the case of Ta7talíya Nahanee shows.","zh":"重新使用原住民名字是对殖民改名做法的抵抗，Ta7talíya Nahanee 的案例即是明证。"},{"en":"Deadnaming, forcible renaming, and mispronouncing names all enforce structures of power and privilege.","zh":"旧名指称、强制改名与错误读音，都在强化既有的权力与特权结构。"}],"terms":[{"en":"matched-guise study","zh":"配对伪装研究（matched-guise study）","defEn":"An experiment holding a stimulus constant while varying the label, or guise, it appears under.","defZh":"一种实验方法：保持刺激材料不变，只改变其标注方式（即 guise），以考察人们的态度。"},{"en":"guise","zh":"伪装标签（guise）","defEn":"The label under which a stimulus is presented, such as the name on a résumé.","defZh":"刺激材料借以呈现给参与者的标签，例如简历顶端所写的姓名。"},{"en":"indexical bleaching","zh":"指称漂白","defEn":"Stripping away a person's connections to family, community, and language by renaming or mispronouncing.","defZh":"通过改名或错误读音，抹去个人与家庭、社群和语言之间的联结。"},{"en":"deadnaming","zh":"旧名指称（deadnaming）","defEn":"Using a trans person's former name, whether accidentally or deliberately.","defZh":"对跨性别者使用其更改前的旧名，无论出于无意还是有意为之。"}],"examples":[{"text":"On one side is Kimberley and on the other is Kimiko.","noteEn":"Names on residence doors prompt guesses about appearance before any meeting.","noteZh":"宿舍门上的名字会让人在见面之前就对邻居的外貌作出猜测。"},{"text":"Rahul Kaur, Asif Sheikh, or Yong Zhang","noteEn":"The same résumé under these names drew fewer callbacks than under Matthew Wilson.","noteZh":"同一份简历署上这些名字，得到的回电比署名 Matthew Wilson 时更少。"},{"text":"Osama Mubbaarak","noteEn":"A typically Arabic male name to which Toronto landlords replied at much lower rates.","noteZh":"典型的阿拉伯男性名字，多伦多房东对这类询问的回复率低得多。"},{"text":"the glottal stop [ʔ]","noteEn":"In Sḵwx̱wú7mesh sníchim orthography, 7 is a letter for this contrastive phoneme.","noteZh":"在 Sḵwx̱wú7mesh sníchim 正字法中，7 是表示这一对立音位的字母，而非数字。"}],"body":[{"en":"Our names are intimately entwined with our personhood. Besides pointing to us as individuals, a name offers clues about our membership in social categories, so people guess at our gender, age, and ethnicity from it. Seeing Kimberley and Kimiko on residence doors, we form expectations about neighbours we have not met. Such clues come from general patterns, not absolutes, so a guess may be wrong.","zh":"名字与人格紧密交织。它既指向作为个体的你，也透露你所属社会范畴的线索，人们会据名字推测其性别、年龄与族裔。设想你看到宿舍两侧门上分别写着 Kimberley 与 Kimiko，尚未见面便已对两位邻居有了预期。这些线索来自普遍模式而非绝对规律，因此猜测可能出错。"},{"en":"A matched-guise study holds a stimulus constant and varies only the guise, or label, under which it appears. Oreopoulos (2011) submitted thousands of mock résumés to Toronto job postings: the same résumé was much more likely to receive a callback under an English-sounding name like Matthew Wilson than under Rahul Kaur, Asif Sheikh, or Yong Zhang, even with a Canadian degree and fluency in English and French. Hogan and Berry (2011) found that Toronto landlords replied far less often to typically Arabic male names like Osama Mubbaarak than to typically English names like Peter McDonald.","zh":"配对伪装研究（matched-guise study）的做法是保持刺激材料不变，只改变其呈现的标签。Oreopoulos（2011）向多伦多的招聘广告投递了数千份模拟简历，发现同一份简历署上 Matthew Wilson 这类英语名字，比署 Rahul Kaur、Asif Sheikh 或 Yong Zhang 得到回电的概率高得多，即便简历写明加拿大大学学位与英法双语能力。同年 Hogan 与 Berry（2011）的研究显示，多伦多房东对 Osama Mubbaarak 这类典型阿拉伯男性名字的回复率，远低于 Peter McDonald 这类典型英语名字。"},{"en":"Many people with non-English names weigh using their own name against adopting an English one that is easier to pronounce. A name is not only a signal to others; it expresses identity and connects a person to family, language, and community. Such names also resist the colonial names assigned in residential schools. Ta7talíya Nahanee, a Sḵwx̱wú7mesh decolonial facilitator, was denied a change to her Sḵwx̱wú7mesh sníchim name because of a rule against numerals like 7, though in that orthography 7 is a letter for the glottal stop [ʔ].","zh":"许多名字并非传统英语的人都会权衡：用本名，还是取一个更易发音的英语名？名字不仅向他人标示关于你的信息，也是对身份的表达，联结着家庭、语言与社群。对重新使用原住民语言的人而言，来自该语言的名字还抵抗着寄宿学校所强加的殖民名字。Sḵwx̱wú7mesh 的去殖民实践者 Ta7talíya Nahanee 申请把证件改为自己的 Sḵwx̱wú7mesh sníchim 名字，却因禁止法律姓名中出现 7 这类数字的规则被拒；而在该正字法中，7 是表示声门塞音 [ʔ] 的字母。"},{"en":"Trans people likewise know the power of names, including the pain of being deadnamed. Most Black train porters in early twentieth-century Canada were simply called George, and during the 2021 federal election Jagmeet Singh was repeatedly called Juggy. Bucholtz (2016) calls this indexical bleaching: renaming or mispronouncing someone strips away their connections to family, community, and language, reinforcing existing structures of power and privilege.","zh":"跨性别者同样深知名字的力量，也知道被用旧名称呼（deadnaming）的痛苦。20 世纪初加拿大火车上的黑人搬运工一律被叫作 George；2021 年联邦大选中，新民主党领袖 Jagmeet Singh 被人反复叫作 Juggy。Bucholtz（2016）把这类做法称为指称漂白（indexical bleaching）：改名或把名字读错，会剥离个人与家庭、社群和语言的联结，从而强化既有的权力与特权结构。"}]},"chapter-014-slug-2-5-pronouns-language-change-and-the-grammar-police":{"title":{"en":"2.5 Pronouns, language change, and the grammar police","zh":"2.5 代词、语言变化与语法警察"},"summary":{"en":"Third-person pronouns replace noun phrases but give only vague clues about referents, and the masculine-feminine distinction can misgender people. This section shows how they and them fill that gap, traces the long history of singular they, and describes how English is extending it to a known single person despite prescriptivist objections, with linguists tracking the change.","zh":"第三人称代词可替代名词短语，却只提供模糊的指称线索，阳阴二分还可能造成错误指称。本节说明 they 与 them 如何填补这一空缺，梳理单数 they 的悠久历史，并描述英语如何在规定主义者的反对声中把它扩展到已知的单个对象，语言学家正在追踪这一变化。"},"points":[{"en":"Third-person pronouns replace noun phrases but give only vague clues about their referents.","zh":"第三人称代词可以替代名词短语，但对所指对象只提供模糊的线索。"},{"en":"The masculine and feminine distinction is too simple, so non-binary people may experience both as misgendering.","zh":"阳性与阴性的二分过于简单，非二元者可能把二者都感受为错误指称。"},{"en":"Singular they has been common for about 600 years and now extends to a known single person.","zh":"单数 they 在英语中已通行约六百年，如今还扩展到指称已知的单个对象。"},{"en":"Prescriptivists object, but dictionaries and the American Dialect Society have recognized singular they.","zh":"规定主义者表示反对，但词典与美国方言学会都已承认单数 they 的地位。"},{"en":"Research links the spread of specific-singular-they to grammar type, social network, and age.","zh":"研究把特指单数 they 的扩散与语法类型、社交网络和年龄联系起来。"}],"terms":[{"en":"third-person pronoun","zh":"第三人称代词","defEn":"A pronoun referring to someone other than speaker or addressee, often replacing a noun phrase.","defZh":"指称说写者与受话者以外的人的代词，常可替代句中的名词短语。"},{"en":"singular they","zh":"单数 they","defEn":"Use of they to refer to a single person, either of unknown or of known identity.","defZh":"在英语中用 they 指称单个的人，该人的身份可能未知，也可能已知。"},{"en":"specific-singular-they","zh":"特指单数 they","defEn":"Singular they used for one person whose identity the speaker actually knows.","defZh":"指称说话人确实知道其身份的单独一个人时所用的单数 they 形式。"},{"en":"prescriptivism","zh":"规定主义","defEn":"The stance that insists on particular usage rules and rejects changes such as singular they.","defZh":"坚持特定用法规则、反对单数 they 之类语言变化的规定主义态度。"},{"en":"language change","zh":"语言变化","defEn":"Ongoing alteration in a language's grammar and usage over time.","defZh":"指语言的语法与用法随时间推移而长期发生的持续变化过程。"}],"examples":[{"text":"Samnang invited him to a movie.","noteEn":"The masculine third-person pronoun here replaces the proper name Steve.","noteZh":"在此句中，阳性第三人称代词替代了专有名词 Steve 的用法。"},{"text":"The passenger in Seat 3A forgot their coat.","noteEn":"In this sentence the ungendered pronoun they replaces the noun phrase.","noteZh":"在这句话里，不分性别的代词 they 替代了那个名词短语。"},{"text":"I don’t know who was in here but they left a big mess","noteEn":"Here the pronoun they leaves the number of referents completely unspecified.","noteZh":"此处 they 完全没有说明所指对象是一个人还是多个人。"},{"text":"Samnang told me they needed an extension.","noteEn":"This illustrates specific-singular-they, where the identity of the single referent is known.","noteZh":"这体现了特指单数 they：所指的那一个人身份是已知的。"}],"body":[{"en":"Like names, pronouns let us express our own identity and make guesses about other people's. In standardized varieties of English, first-person pronouns refer to the speaker, signer, or writer, second-person pronouns to the addressee, and third-person pronouns to someone else, often replacing a noun phrase. Third-person singular pronouns give only vague clues: it suggests a thing, he a boy or man, she a woman or girl.","zh":"与名字类似，我们也用代词表达自身身份，并推测他人的身份。在标准英语变体中，第一人称代词指说、写或打手语的人，第二人称代词指受话者，第三人称代词指他人，常可替代句中的名词短语。第三人称单数代词只给出模糊线索：it 指物，he 指男孩或男人，she 指女人或女孩。"},{"en":"Those broad categories can still do harm and exclude people. Many cultures expect appropriately gendered pronouns even for a baby who cannot be offended, and after infancy being misgendered ranges from embarrassing to outright dangerous. A two-way masculine and feminine distinction is too simple for human gender variation, so non-binary, genderqueer, or gender-fluid people may experience both he/him and she/her as misgendering.","zh":"这些范畴虽然宽泛，却仍可能造成伤害与排斥。许多文化都期待我们按性别使用相应代词，面对完全不会介意的婴儿也会问是男孩还是女孩；而过了婴儿期，被用错误的代词指称可能令人尴尬，甚至危险。阳性与阴性的二分过于简单，无法描述人类性别的丰富变异，因此非二元、性别酷儿或性别流动者可能把 he/him 与 she/her 都感受为错误指称。"},{"en":"The pronouns they and them fill this gap. They specifies neither animacy nor gender, nor even number: in I don’t know who was in here but they left a big mess we cannot tell how many people left the mess. Singular they has been common in English for about 600 years.","zh":"they 与 them 正可填补这一空缺。they 不指明所指是否有生命、是男是女，甚至不指明单复数：在 I don’t know who was in here but they left a big mess 中，我们无法知道留下烂摊子的是一个人还是许多人。单数 they 在英语中已通行约六百年。"},{"en":"English is now extending they to a single person whose identity is known, as in Samnang told me they needed an extension. Prescriptivists object, and The Chicago Manual of Style calls singular they ungrammatical, yet the American Dialect Society named it Word of the Year in 2015 and Merriam-Webster did so in 2019. English changed similarly when thou and thee gave way to you for both numbers, prompting plural forms like y'all, you guys, or youse. Bjorkman (2017), Ackerman (2019), Conrod (2019), and Konnelly and Cowper (2020) trace how the change is spreading; Conrod (2017) advises slowing down, listening to people who use it, and practising.","zh":"如今英语又把 they 扩展到指称身份已知的单个对象，如 Samnang told me they needed an extension。规定主义者对此表示反对，《芝加哥手册》称单数 they 仍被视为不合语法，然而美国方言学会在 2015 年将其评为年度词汇，Merriam-Webster 词典也在 2019 年如此。数百年前英语的代词系统经历过类似变化：thou 与 thee 让位于兼表单复数的 you，于是 y'all、you guys 或 youse 这类复数形式应运而生。Bjorkman（2017）、Ackerman（2019）、Conrod（2019）以及 Konnelly 与 Cowper（2020）追踪了这一变化的扩散：Bjorkman 对比保守与创新的语法，Ackerman 把它与跨性别和非二元朋友的多少相联系，Conrod 发现年轻人更常用，Konnelly 与 Cowper 则描写了进行中的三个阶段。没人能阻止语言变化，但使用者可以加快它；Conrod（2017）建议放慢速度、倾听使用者的语言并多加练习。"}]},"chapter-015-slug-2-6-linguistic-law-enforcement":{"title":{"en":"2.6 Linguistic law enforcement","zh":"2.6 语言的执法"},"summary":{"en":"Criticizing most kinds of social difference is considered rude, yet criticizing language that deviates from the privileged standard is expected and even encouraged, so prescriptive grammar functions like law enforcement. This section examines two targets of that policing, women's voices and unfamiliar accents, and shows how expectations and stigma produce real consequences in employment, housing, and education.","zh":"批评多数类型的社会差异会被视为无礼，但批评偏离特权标准的语言使用却被期待甚至鼓励，规定性语法因而像执法一样运作。本节考察这种管束的两个对象——女性的嗓音和陌生的口音，并说明预期与污名如何在就业、住房和教育中造成实际后果。"},"points":[{"en":"Criticizing other social differences is rude, but criticizing non-standard language use is expected and encouraged.","zh":"批评其他社会差异被视为无礼，而批评偏离特权标准的语言使用却被期待甚至鼓励。"},{"en":"Prescriptive grammar is used like law enforcement, especially against women's voices and unfamiliar accents.","zh":"规定性语法被当作执法工具，尤其针对女性的嗓音和与主流不同的口音。"},{"en":"Vocal fry is a systematic creaky voice quality, yet it is judged far more harshly in women than in men.","zh":"气泡音是一种系统性的嘎裂发声，但女性使用时所受的苛责远多于男性。"},{"en":"An L2 accent is shaped by L1 phonology, and accent stigma harms employment, housing, and education.","zh":"第二语言口音受第一语言音系塑造，口音污名会损害就业、住房和教育机会。"},{"en":"Listeners' expectations, not the accent itself, can reduce comprehension, but perceptual adaptation improves it.","zh":"影响理解的是听者的预期而非口音本身，而知觉适应能够改善这种理解。"}],"terms":[{"en":"vocal fry","zh":"气泡音","defEn":"A voice quality produced with very low frequency vibrations of the vocal folds, sounding creaky.","defZh":"声带以极低频率振动而发出的语音，听上去嘎吱作响，也称嘎裂发声。"},{"en":"creak","zh":"嘎裂声","defEn":"The technical linguistic term for this creaky voice quality in speech.","defZh":"语言学术语，指上述嘎吱作响的发声方式，系统性地出现于许多语言的语音、音系与韵律中。"},{"en":"accent","zh":"口音","defEn":"A way of pronouncing a language; everyone has one, but only unfamiliar ones are noticed.","defZh":"一种语言的发音方式；人人都有口音，但只有与主流不同的口音才被注意并蒙受污名。"},{"en":"perceptual adaptation","zh":"知觉适应","defEn":"Improved comprehension of a talker that grows with experience paying attention to them.","defZh":"随着听者注意某位说话者的经验增加，对其话语的理解力随之提高的现象。"},{"en":"matched-guise study","zh":"配对变体实验","defEn":"An experiment presenting the same voice with different social information, such as a face.","defZh":"实验方法：使用同一位说话者的录音，配以不同的社会信息（如照片），以考察听者评价的变化。"},{"en":"stigma","zh":"污名","defEn":"Negative attitudes and expectations attached to a stigmatized accent or language variety.","defZh":"社会附加于某种口音或语言变体之上的负面态度与期待，会带来现实的后果。"}],"examples":[{"text":"The negative perceptions of vocal fry are stronger for female voices relative to male voices","noteEn":"Anderson et al. (2014), who advised young American women to avoid vocal fry.","noteZh":"安德森等人（2014）的研究结论，他们据此建议年轻美国女性避免使用气泡音。"},{"text":"if your L1 is English and you learn Japanese as an L2, your accent in Japanese is likely to be different from that of your classmate whose L1 is Korean","noteEn":"An illustration of how the phonology of the L1 shapes an L2 accent.","noteZh":"说明第一语言的音系如何塑造第二语言的口音，母语不同的学习者口音因此有别。"},{"text":"For any given voice, the listeners rated the talker as having a stronger accent when they saw a Chinese Canadian face than when they saw a white Canadian face","noteEn":"Babel and Russell's (2015) matched-guise finding about expectations and intelligibility.","noteZh":"巴贝尔和拉塞尔（2015）配对变体实验的发现，显示预期如何影响口音评价与理解。"}],"body":[{"en":"Criticizing other kinds of social difference is widely considered rude, but criticizing language that deviates from the privileged standard is expected, so prescriptive grammar works like law enforcement. Objections to they/them pronouns for non-binary people are typically framed as grammar, yet Bradley (2019) found that prescriptive views of grammar accompany conservative views of the gender binary. Women's voices are policed too: complaints about uptalk gave way in the 2010s to a panic about vocal fry, a creaky voice quality produced with very low frequency vibrations of the vocal folds. Creak is systematic in the phonetics, phonology, and prosody of many languages, and Davidson (2020) reports that creaky speakers sound more bored, more relaxed, less intelligent, and less confident.","zh":"批评其他类型的社会差异通常被视为无礼，但批评偏离特权标准的语言使用却不仅被容忍，甚至受到期待与鼓励，规定性语法规范因而像执法一样在维持社会秩序。对非二元性别人士使用 they/them 代词的反对意见常以语法为说辞，但布拉德利（2019）发现，持规定性语法观的人往往也对性别二元论持保守立场。女性的嗓音同样受到管束：对升调的抱怨在 2010 年代转向对气泡音的道德恐慌；气泡音是声带以极低频率振动、听来嘎裂的发声方式，而嘎裂声在许多语言的语音、音系和韵律中都是系统性的。戴维森（2020）指出，使用这种发声的说话者会被听成更无聊、更放松、更不聪明、更不自信。"},{"en":"Men and women creak about equally often, but older listeners find it far more irritating when women do it, and Anderson et al. (2014) advised young American women to avoid vocal fry to maximize labor market opportunities. Accent is policed in similar ways. Everyone has an accent, yet only unfamiliar ones are noticed and stigmatized, including L1 varieties such as Black English, the varieties of the southeastern United States, and Newfoundland English. Because an L2 mental grammar is shaped by the experience of an L1, L2 accents vary with the speaker's first language. The costs are fewer job interviews, unrecognized skills, trouble renting housing, less credible court testimony, and children being disproportionately labelled with learning disabilities.","zh":"男女使用气泡音的频率大致相当，但年长的听者觉得女性使用时更令人恼火，安德森等人（2014）甚至建议年轻美国女性避免气泡音以增加劳动市场机会。口音所受的管束同样明显：人人都有口音，但只有与主流不同的口音才被注意并蒙受污名，其中包括黑人英语、美国东南部诸变体以及纽芬兰英语等第一语言变体。由于第二语言的心理语法由第一语言的经验塑造，第二语言口音的差异与说话者的第一语言有关。代价十分具体：更难获得面试机会、技能不被认可、租房受阻、法庭证词不受重视，以及儿童被不成比例地贴上学习障碍标签。"},{"en":"Expectations also shape comprehension. Babel and Russell (2015) presented identical L1 Canadian English voices with either a white Canadian or a Chinese Canadian face; listeners judged the talkers as more strongly accented and transcribed their sentences less accurately with the Chinese Canadian face, a mismatch of expectations in a region where over 40% of people speak Cantonese or Mandarin. Perceptual adaptation offers a remedy: the longer we attend to a talker, and the more unfamiliar accents we have heard, the better we understand.","zh":"听者的预期也会影响理解。巴贝尔和拉塞尔（2015）的配对变体实验把同一批第一语言为加拿大英语的说话者的录音，分别配上白人加拿大人或华裔加拿大人的照片；看到华裔面孔时，听者认为说话者口音更重，听写句子也更不准确，这正是出现在超过四成人口讲粤语或普通话地区的预期错配。知觉适应则提供了出路：我们越是注意某个说话者、听过的陌生口音越多，就越能听懂对方所说的话。"}]},"chapter-016-slug-2-7-legally-enshrined-harms":{"title":{"en":"2.7 Legally enshrined harms","zh":"2.7 法律明文确立的伤害"},"summary":{"en":"Language policing is not only carried out by individuals but also by governments through language policy, which can unify or divide and can erase or reinforce social identities. This section traces Canada's official English-French bilingualism, the Official Languages Act, the residential school policy and linguicide, and the 2019 Indigenous Languages Act, showing how laws continue to shape whose languages count.","zh":"语言管束不只来自个人，也来自政府通过语言政策所行使的权力，这些政策既能促成团结也能制造分裂，既能抹除也能强化身份认同。本节梳理加拿大英语—法语官方双语制的由来、《官方语言法》、寄宿学校政策与语言灭绝，以及 2019 年《原住民语言法》，说明法律如何持续决定哪些语言算数。"},"points":[{"en":"Governments wield power through language policy, which can erase or reinforce identities and encourage or forbid languages.","zh":"政府通过语言政策行使权力，既可能抹除也可能强化身份认同，鼓励或禁止某些语言。"},{"en":"The Official Languages Act of 1969 made French and English official but recognized no Indigenous languages.","zh":"1969 年的《官方语言法》确立英语和法语的地位，却未承认任何原住民语言。"},{"en":"Residential schools punished Indigenous children for using home languages, a policy of assimilation and linguicide.","zh":"寄宿学校因原住民儿童使用母语而施罚，这是同化政策，也是对语言的扼杀。"},{"en":"The 2019 Indigenous Languages Act provides protections and funding for reclaiming and revitalizing Indigenous languages.","zh":"2019 年《原住民语言法》为原住民语言的恢复与振兴提供保障和资金。"},{"en":"Quebec's laws protect French from English assimilation but also suppress Cree, Mohawk, and other languages.","zh":"魁北克的语言法保护法语免受英语同化，却也压制了克里语、莫霍克语等语言。"}],"terms":[{"en":"language policy","zh":"语言政策","defEn":"Government or institutional decisions about which languages may be used, taught, or displayed.","defZh":"政府或机构对语言使用、教学和公开展示所作的规定，可用以促进团结，也可制造分裂。"},{"en":"official language","zh":"官方语言","defEn":"A language given legal recognition by a government, unlike languages without that status.","defZh":"经政府法律承认的语言；是否获得法律承认，决定了哪些语言被列为官方语言。"},{"en":"Official Languages Act","zh":"官方语言法","defEn":"The 1969 Canadian law making French and English official and expanding Francophone access.","defZh":"加拿大 1969 年颁布的法律，确立英语和法语为官方语言，并扩大了法语使用者的教育与就业机会。"},{"en":"residential school","zh":"寄宿学校","defEn":"An institution where Indigenous children were punished for using home languages and taught only in English or French.","defZh":"原住民儿童被迫入学、因使用母语而受罚的机构，只以英语或法语授课，目的是同化他们。"},{"en":"linguicide","zh":"语言灭绝","defEn":"The killing of a language, as through policies that punish children for using it.","defZh":"对语言的扼杀；例如寄宿学校惩罚儿童使用母语，迫使其语言中断代际传承。"},{"en":"Indigenous Languages Act","zh":"原住民语言法","defEn":"The 2019 Canadian law providing protections and funding for reclaiming and revitalizing Indigenous languages.","defZh":"加拿大 2019 年通过的法律，为原住民语言的保护、恢复与振兴提供保障和经费。"}],"examples":[{"text":"Based on my experience growing up in Quebec, I was denied the chance to learn French during my time in the federal government day schools","noteEn":"Mary Simon (2021), criticized as Governor-General for lacking French proficiency.","noteZh":"玛丽·西蒙（2021）的话；她因法语不够流利而受到批评，尽管英语和因纽特语流利。"},{"text":"linguicide, or killing of language","noteEn":"The term used for policies that caused children to stop using their home languages.","noteZh":"用以指称那些使儿童放弃母语的政策，其造成的伤害至今仍在延续。"},{"text":"the majority of Cree and Mohawk speakers in Quebec use English as their second language","noteEn":"Showing how Quebec's French-protection laws disadvantage speakers of other languages.","noteZh":"说明魁北克保护法语的法律如何使其他语言的使用者处于不利地位。"},{"text":"French on signs to come first and to be twice as large as other languages","noteEn":"One requirement of Quebec's language laws regulating the public landscape.","noteZh":"魁北克语言法对公共空间语言景观的规定之一，用以强化法语的地位。"}],"body":[{"en":"Language policing is not only individual; governments also wield power through language policy. Such policies can create unity or division, erase or reinforce identities, demand proof of competence, or regulate what appears in public space. In the country now known as Canada, French and English are official languages because of legal recognition, while many other languages are used on these lands.","zh":"语言管束不仅由个人实施，政府也通过语言政策行使权力。这类政策可以促成团结，也可以制造分裂；可以抹除身份认同，也可以强化它；可以要求证明语言能力，也可以规定公共空间里允许出现哪些语言，其动机可正可负。在今天称为加拿大的这片土地上，法语和英语因法律承认而成为官方语言，但这里还使用着许多其他语言。"},{"en":"The Official Languages Act was instituted in 1969 by Prime Minister Pierre Trudeau in response to increasing Francophone nationalism in Quebec, where an Anglophone minority then dominated industry, commerce, and finance. It made space for Francophones, improved education and employment outside Quebec, and helped make New Brunswick officially bilingual; the Supreme Court of Canada overturned Manitoba's English-only law once the Act passed. Its major shortcoming is that it neither protects nor recognizes the Indigenous languages used here for centuries before Canada existed.","zh":"1969 年，总理皮埃尔·特鲁多面对魁北克日益高涨的法裔民族主义而推行《官方语言法》。当时魁北克的英语少数群体主导着工业、商业和金融部门，该法为法语使用者开辟了在更多场合使用本族语言的空间，改善了魁北克以外法语使用者的教育与就业机会，并促使法语人口众多的新不伦瑞克省成为正式的双语省份；曼尼托巴省原本以法律规定英语为唯一官方语言，该法通过后即被加拿大最高法院推翻。它的一大缺陷在于，对在加拿大建国之前就已在此使用了许多世纪的原住民语言，既不提供保护，也不予承认。"},{"en":"The Canadian government has also used language policy to oppress Indigenous peoples. Residential schools punished Indigenous children for using their home languages, instructing them only in English and French to assimilate them into colonial society; many children stopped using their community language and did not pass it on. Such policies can be called linguicide, the killing of language, and the harms continue. The Truth and Reconciliation Commission of Canada called in 2015 for policies and funding to support Indigenous languages, and the Indigenous Languages Act of 2019 provided protections and funding for reclaiming and revitalizing them.","zh":"加拿大政府还利用语言政策压迫原住民。寄宿学校因原住民儿童使用母语而施罚，只以英语和法语授课，目的是把他们同化进殖民社会；许多儿童因此不再使用自己社区的语言，也没有把它传给下一代。这类政策可称为语言灭绝（linguicide），即对语言的扼杀，其伤害至今仍在延续。2015 年，加拿大真相与和解委员会呼吁制定支持原住民语言的政策并提供资金；2019 年通过的《原住民语言法》为此类语言的恢复与振兴提供了保护和经费。"},{"en":"The effects of this focus persist. When Mary Simon became Governor-General in 2021, she was criticized for lacking French proficiency even though she is bilingual in English and Inuktitut, and she attributed this to Canadian education policy. Quebec's language laws protect French from assimilation into the anglophone majority, but they also suppress other languages: since most Cree and Mohawk speakers in Quebec use English rather than French as a second language, these laws hinder their access to education and provincial services.","zh":"英语—法语双语这一官方重心带来的后果至今可见。2021 年玛丽·西蒙出任总督时，因法语不够流利而受到批评，尽管她的英语和因纽特语都很流利，她把这番经历归因于加拿大的教育政策。魁北克的语言法保护法语不被加拿大其他地区的英语多数同化，但也压制了其他语言：魁北克大多数克里语和莫霍克语使用者以英语而非法语作为第二语言，因此这些法律使他们更难获得教育和省级服务。"}]},"chapter-017-slug-2-8-exercise-your-linguistics-skills":{"title":{"en":"2.8 Exercise your linguistics skills","zh":"2.8 练习你的语言学技能"},"summary":{"en":"Four exercises let learners apply the chapter's concepts to their own experience. They use morphology to compare standardized language with standard language, reflect on feelings about an L2 accent, analyse how names and nicknames vary across relationships, and examine swearing in different social contexts in terms of face.","zh":"本节提供四个练习，让学习者把本章概念应用于自身经验：用形态学知识比较“标准化语言”与“标准语”，反思自己对第二语言口音的感受，分析称呼与昵称如何因人际关系而异，并从面子角度考察不同社会语境中的脏话使用。"},"points":[{"en":"The exercises ask learners to apply morphology, reflect on accent attitudes, and analyse naming and swearing.","zh":"这些练习要求学习者运用形态学知识、反思口音态度，并分析称呼与脏话的使用。"},{"en":"Learners compare the terms standardized language and standard language and consider why linguists prefer the former.","zh":"学习者比较“标准化语言”与“标准语”两个术语，并思考语言学家为何偏好前者。"},{"en":"Learners examine how naming choices vary across relationships and what happens when someone uses an other name.","zh":"学习者考察称呼选择如何因人际关系而异，以及他人使用自己另一个名字时会产生什么后果。"},{"en":"Learners analyse swearing in different social contexts in terms of threats to positive and negative face.","zh":"学习者从正面面子与负面面子所受影响的角度，分析不同社会语境中的脏话使用。"}],"terms":[{"en":"morpheme","zh":"语素","defEn":"The smallest meaningful unit of language, such as the -ize added to these words.","defZh":"语言中最小的音义结合单位，如加在这些词后面的 -ize，本身携带意义。"},{"en":"standardized language","zh":"标准化语言","defEn":"A variety that has undergone standardization through social processes, rather than being inherently standard.","defZh":"经由社会标准化过程而形成的变体，并非天生就“标准”的、优于其他变体的语言。"},{"en":"standard language","zh":"标准语","defEn":"The prescriptive label that treats one variety as inherently correct and superior.","defZh":"规定性标签，把某一变体视为天生正确、优于其他语言变体的说法，并非客观事实。"},{"en":"face","zh":"面子（英文原词 face）","defEn":"The public self-image a speaker claims in interaction, which can be positive or negative.","defZh":"交际中说话者为自己主张的公开自我形象，可分为正面面子与负面面子。"},{"en":"positive face","zh":"正面面子","defEn":"The desire to be approved of, liked, and accepted by others.","defZh":"希望得到他人认可、赞许与接纳，从而确认自己被喜欢的需求。"},{"en":"negative face","zh":"负面面子","defEn":"The desire to be unimpeded, with one's actions free from imposition.","defZh":"希望行动不受他人干扰、不被强加要求，从而保持自由的需要。"}],"examples":[{"text":"prioritized, finalized, Americanized, revitalized","noteEn":"Words given for analysing what the -ize morpheme contributes to meaning.","noteZh":"题目给出的词，用以分析 -ize 语素为词义增添了什么样的意义。"},{"text":"standardized language and standard language","noteEn":"The two competing terms learners are asked to contrast using morphology skills.","noteZh":"要求学习者借助形态学技能加以对比的两个术语，思考选用哪一个及其理由。"}],"body":[{"en":"This section offers four exercises that let learners apply the chapter's ideas to their own language experience. The first uses morphology skills to consider what the -ize morpheme adds to the meaning of prioritized, finalized, Americanized, and revitalized, and to ask what difference in meaning separates the term standardized language from the term standard language and why a writer might choose one over the other. The second turns to the learner's own L2 accent, asking how they feel about it, which factors shape those feelings, and whether those factors concern the language itself or instead prestige and power.","zh":"本节提供四个练习，让学习者把本章的概念应用于自身的语言经验。第一题用形态学技能思考 -ize 语素为 prioritized、finalized、Americanized、revitalized 这几个词的意义增添了些什么，并追问 standardized language 与 standard language 两个术语在意义上有什么差别，以及人们为何会选择其中一个。第二题转向学习者自己在第二语言中的口音，请其思考对口音的感受、哪些因素塑造了这些感受，以及这些因素与语言本身有关，还是与声望和权力有关。"},{"en":"The remaining two exercises concern naming and swearing. Learners consider whether they use different names or nicknames with different people, what factors influence which name they use with different groups, and what happens if someone uses their other name. The final exercise asks for at least one social context in which using swear words is offensive and one in which swearing is acceptable, and for each context asks learners to describe the role that swearing plays in terms of face, deciding whether positive or negative face is threatened or enhanced.","zh":"后两个练习涉及称呼与脏话。学习者需要思考自己是否对不同的人使用不同的名字或昵称，哪些因素影响他们面对不同群体时所选用的名字，以及别人用了自己“另一个”名字时会发生什么。最后一题要求至少分别举出一个使用脏话会冒犯他人的社会语境和一个可以接受脏话的语境，并针对每种语境说明脏话就面子而言起什么作用：受到威胁或被增强的是正面面子还是负面面子。"}]}});
